function ezCount(root){
  const els = [...root.querySelectorAll("[data-ezc]")]; if (!els.length || reduce) return;
  const t0 = performance.now(), D = 900;
  els.forEach(el => { el.dataset.end = el.textContent; el.textContent = (0).toFixed(+el.dataset.dec || 0); });
  const step = now => { const k = Math.min(1, (now - t0) / D), e = 1 - Math.pow(1 - k, 3);
    els.forEach(el => { el.textContent = k >= 1 ? el.dataset.end : (+el.dataset.ezc * e).toFixed(+el.dataset.dec || 0); });
    if (k < 1) requestAnimationFrame(step); };
  requestAnimationFrame(step);
}
// 教材の表紙（共通デザインの .cover）：場面の言葉から色の組と英単語を選ぶ
