const EZ_PW = [
  {k: "speak", ja: "語る", en: "SPEAK", g: "trust", how: "AI英会話で測ります", tip: "自分のこと・自分の仕事を、気持ちをこめて英語で語ってみよう。", go: `data-ez="drill"`, btn: "1分感情スピーチをする", bs: "語順の日本語を見て、1分だけ英語で話す"},
  {k: "connect", ja: "つなぐ", en: "CONNECT", g: "trust", how: "AI英会話で測ります", tip: "相手の話に「リアクション＋一言」、そして自分の経験・意見で返してみよう。", go: `data-ez="talk"`, btn: "AI英会話をする", bs: "ミートアップ・乾杯の場面で約5分"},
  {k: "lead", ja: "主導する", en: "LEAD", g: "trust", how: "AI英会話で測ります", tip: "自分からトピックの質問をして、深掘りの質問をもう1つ重ねてみよう。", go: `data-ez="talk"`, btn: "AI英会話をする", bs: "自分から質問を3回するのが目標"},
  {k: "propose", ja: "提案する", en: "PROPOSE", g: "move", how: "AI英会話（会議・商談）で測ります", tip: "目的 → 相手のメリットと根拠 → 次のアクション、の順で提案してみよう。", go: `data-ez="talk"`, btn: "AI英会話をする", bs: "会議・商談の場面を選んで約5分"},
  {k: "deliver", ja: "伝わる", en: "DELIVER", g: "base", how: "音読チェック・2秒応答で測ります", tip: "155語/分の速さと、2秒以内の返事。伝わる声の筋トレをしよう。", go: `data-ez="read"`, btn: "音読チェックをする", bs: "教材の段落を読んで、速さと発音を測る"}];
