  rxsugoi: '<path d="M12 3l2 5.6 5.9.4-4.6 3.7 1.6 5.8L12 15.2 7.1 18.5l1.6-5.8L4.1 9l5.9-.4z"/>',
  rxwakaru: '<path d="M12 20s-7.5-4.6-7.5-10.2A4.1 4.1 0 0 1 12 7.4a4.1 4.1 0 0 1 7.5 2.4C19.5 15.4 12 20 12 20z"/>',
