const PF_SETS = new WeakMap();
function pfSets(p){
  if (p && PF_SETS.has(p)) return PF_SETS.get(p);
  const s = pfSets0(p); if (p) PF_SETS.set(p, s); return s;
}
function pfSets0(p){
  p = p || pfEmpty();
  return {langs: new Set((p.langs || []).map(x => pfNorm(x.l)).filter(l => !PF_COMMON_SKIP.has(l))), hobbies: new Set((p.hobbies || []).map(pfNorm)), skills: new Set((p.skills || []).map(pfNorm)),
    goods: new Set((p.goods || []).map(pfNorm)), cc: new Set([...((p.abroad || {}).cc || []), ...(p.markets || [])].map(v => pfNorm(pfCcName(v)))),
    region: new Set(((p.abroad || {}).cc || []).map(pfCcRegion)), job: new Set(p.job ? [pfNorm(p.job)] : [])};
}
// あなたとの共通点：[[種類, 値], …]
function pfCommon(mine, other){
  if (!mine) return [];
  const A = pfSets(mine), B = pfSets(other), out = [];
  const lab = {langs: "言語", hobbies: "趣味", skills: "スキル", goods: "商材", cc: "国", job: "仕事"};
  Object.keys(lab).forEach(k => B[k].forEach(v => { if (v && A[k].has(v)) out.push([lab[k], v]); }));
  if (mine.eng && other.eng && mine.eng === other.eng) out.push(["英語", (PF_ENG_L.find(x => x[0] === other.eng) || ["", ""])[1]]);
  return out;
}
const pfIsCommon = (mine, k, v) => !!mine && pfSets(mine)[k] && pfSets(mine)[k].has(pfNorm(k === "cc" ? pfCcName(v) : v));

/* ---------- マイ＞プロフィール（編集） ---------- */
function pfMyCardHtml(){
  if (!ME || ME.viewer) return "";
  const me = PF.me || {pf: pfEmpty(), dir: false}, ph = pfMyPh(), pct = pfFill(me.pf || pfEmpty(), ph);
  if (!PF.me && !PF.loading && pfReady()) pfLoad().then(() => { const el = $("pfMyCard"); if (!el) return; el.outerHTML = pfMyCardHtml(); const n = $("pfMyCard"); if (n) n.addEventListener("click", () => myGo("profile2")); });
  return `<button type="button" class="pf-mycard tap" id="pfMyCard" data-my="profile2">
    <span class="pf-mycard-av">${avHtml(me.icon || snsIcon(), ph, "lg")}</span>
    <span class="pf-mycard-b"><span class="ds-eyebrow">PROFILE</span><b>プロフィール</b><small>${me.dir ? "名鑑に載っています" : "名鑑にはまだ載っていません"}・充実度 <b class="num">${pct}</b>%</small><i class="ds-bar"><i style="width:${pct}%"></i></i></span>${ico("chevron")}</button>`;
}
const pfTagHtml = (k, list, sug, ph) => `<div class="pf-tags" data-pftags="${k}">${list.map((v, i) => `<span class="pf-tag">${esc(v)}<button type="button" data-pftagx="${k}:${i}" aria-label="${esc(v)}を外す">×</button></span>`).join("")}
  <input type="text" class="pf-tagin" data-pftagin="${k}" maxlength="20" placeholder="${esc(ph || "入れて Enter")}" enterkeyhint="done"></div>
  ${sug ? `<div class="pf-sugs">${sug.filter(s => !list.includes(s)).slice(0, 12).map(s => `<button type="button" class="pf-sug" data-pfsug="${k}" data-v="${esc(s)}">＋${esc(s)}</button>`).join("")}</div>` : ""}`;
const pfCnt = (v, n) => `<small class="pf-cnt"><b class="num">${[...String(v || "")].length}</b>/${n}</small>`;
