/* ---------- 今日の10分の画面（KZ="daily"） ---------- */
let EZSP = null, EZRUN = 0;
function ezStop(){ EZRUN++; ezSpAbort(); ezVaStop(); }
document.addEventListener("visibilitychange", () => { if (document.hidden){ ezSpAbort(); ezVaStop(); } });
window.addEventListener("pagehide", () => { ezSpAbort(); ezVaStop(); });
function ezGoDaily(){
  const st = ezDay(), m = ezLesson(st);
  if (!m){ toast("台本ができると、今日の10分をはじめられます"); return; }
  if (st.done){ const c = st.course; Object.assign(st, {step: 0, rep: 0, done: false, sp: [], rx: [], rec: "", pw0: null, course: c, again: (st.again || 0) + 1}); }
  if (!st.m) st.m = m.id;
  if (!st.pw0){ st.pw0 = Object.fromEntries(ezPowers(null).map(a => [a.k, a.p])); st.rx0 = (() => { const v = reactLog().filter(x => x && x.ms > 0).map(x => x.ms); return v.length ? Math.min(...v) : null; })(); }
  ezDaySave(st);
  hush(); KZ = "daily"; renderKz(); window.scrollTo(0, 0);
}
function renderDaily(){
  const box = $("kzwrap"), st = ezDay(), m = ezLesson(st);
  if (!m){ KZ = null; renderKz(); return; }
  if (st.done){ ezDoneRender(); return; }
  const C = ezSteps(st), s = C[st.step] || C[0], f = ezFocus(st.pw0 ? EZ_PW.map(a => ({...a, p: st.pw0[a.k]})) : null);
  box.innerHTML = `<button class="more kzback" type="button" id="ezdBack">← 英語のトップへ</button>
    <div class="ezd">
      <div class="ezd-bar"><b>${st.step + 1} / ${C.length}　${esc(s.t.replace(/×\d+$/, ""))}</b>${s.k === "sp" ? `<span class="ezd-chip">${s.n}回中 ${Math.min(s.n, st.rep + 1)}回目</span>` : f ? `<span class="ezd-chip">${esc(f.ja)}力</span>` : ""}</div>
      <div class="ezd-prog" aria-hidden="true">${C.map((x, i) => `<span class="${i < st.step ? "on" : i === st.step ? "now" : ""}"></span>`).join("")}</div>
      <div id="ezdBody"></div></div>`;
  $("ezdBack").addEventListener("click", () => { ezStop(); quiet(); KZ = null; renderKz(); window.scrollTo(0, 0); });
  ({ear: ezStepEar, sp: ezStepSp, ai: ezStepAi, rx: ezStepRx})[s.k](st, m, s, f);
}
// 次のステップへ（最後なら終わった画面）。進み具合はいつも保存してある最新のものから（画面を描いたときの古い値で上書きしない）
function ezNext(patch){
  const st = ezDay(); if (patch) Object.assign(st, patch);
  const C = ezSteps(st), s = C[st.step];
  if (s && s.k === "sp" && st.rep + 1 < s.n){ st.rep++; ezDaySave(st); renderDaily(); window.scrollTo(0, 0); return; }
  st.step++; st.rep = 0;
  if (st.step >= C.length){ st.done = true; st.doneT = Date.now(); }
  ezDaySave(st); quiet(); renderDaily(); window.scrollTo(0, 0);
}
// ① 耳ならし：今日の台本を通しで聞く（速さを選べる。最後まで聞いた速さが「聞ける速さ」）
function ezStepEar(st, m){
  const b = $("ezdBody"), A = kzA(m), lines = (m.paras || []).length ? kzPara(m).map((p, i) => ({h: (A.paras || [])[i], text: p.en, label: `段落${p.n}`})) : (m.lines || []).map((l, i) => ({h: (A.lines || [])[i], text: l.en, label: (l.sp === "partner" ? "相手：" : "あなた：") + l.en}));
  b.innerHTML = `<p class="ezd-lead">今日の台本「${esc(m.title)}」を聞きます。英語のリズムに耳をならしましょう。</p>
    <img class="ezd-pic" src="${esc(kzScene(m))}" alt="" loading="lazy" onerror="this.remove()">
    <div class="ezd-ear" id="ezEar">${lines.map((x, i) => `<p data-i="${i}">${wordSpans(x.text)}</p>`).join("")}</div>
    <div class="kzbar"><button class="btn" type="button" id="ezEarGo">${ico("play", "fill")}聞く</button>${rateBar()}</div>
    <button class="ds-btn-gold ezd-next" type="button" id="ezEarNext">聞けた！ 次へ</button>`;
  bindRate(b);
  $("ezEarGo").addEventListener("click", async () => {
    hush(); const run = KZ_SPEAK, ear = $("ezEar");
    const ok = await playSeq(lines, {gap: 400, start: k => { ear.querySelectorAll("p").forEach(p => p.classList.toggle("now", +p.dataset.i === k)); const el = ear.querySelector(`p[data-i="${k}"]`); el && el.scrollIntoView({behavior: reduce ? "auto" : "smooth", block: "nearest"}); },
      time: (k, t) => { const el = ear.querySelector(`p[data-i="${k}"]`); el && lightWords(el, lines[k].h, t); }});
    ear.querySelectorAll(".wd").forEach(w => w.classList.remove("on", "did")); ear.querySelectorAll("p").forEach(p => p.classList.remove("now"));
    if (ok && run === KZ_SPEAK){ kzSave({id: m.id, step: "ear"}); const cur = ezDay(); cur.w.ear = 1; ezDaySave(cur); const n = $("ezEarNext"); if (n) n.textContent = "聞けた！ 次へ"; toast(`最後まで聞けました（${ezRateTxt(KZRATE)}）`); }
  });
  $("ezEarNext").addEventListener("click", () => { hush(); ezNext(); });
}
// ② 1分スピーチ：語順の日本語を見て → イメージ → 英語で1分。マイクの認識で語数を数える。週の最初の1回は声をアルバムに
const EZ_SP_SEC = 60;
function ezStepSp(st, m, s, f){
  const b = $("ezdBody"), list = ezParas(m, (f && f.k) || "speak", s.n), src = list[st.rep] || list[0];
  if (!src){ b.innerHTML = `<p class="note">この台本には話す段落がありません。</p><button class="ds-btn-gold ezd-next" type="button" id="ezSkip">次へ</button>`; $("ezSkip").addEventListener("click", () => ezNext()); return; }
  const key = `${m.id}:${src.p.n}`, prev = ezSpLog().filter(x => x.k === key || x.m === m.id), last = prev.length ? prev[prev.length - 1].w : null;
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition, Cc = 2 * Math.PI * 34;
  b.innerHTML = `<div class="ezd-sp">
      <p class="ezd-order" id="ezOrder">${orderHtml(src.p.order || src.p.ja || src.p.en)}</p>
      <p class="ezd-how">語順の日本語を見て → 目を閉じてイメージ → 英語で話す</p>
      <div class="ezd-ring"><svg viewBox="0 0 80 80" aria-hidden="true"><circle cx="40" cy="40" r="34" class="bg"/><circle cx="40" cy="40" r="34" class="fg" id="ezRing" stroke-dasharray="${Cc.toFixed(1)}" stroke-dashoffset="0"/></svg><b class="num" id="ezSec">${EZ_SP_SEC}</b></div>
      <div class="ezd-cnt" aria-live="polite"><span>${SR ? "いまの1分で話せた" : "話せた語数"}</span><b class="num" id="ezW">0</b><small>語</small><em id="ezWd"></em></div>
      ${SR ? "" : `<p class="mapnote warn">この端末では、話した語数を数えられません（声の認識が使えない）。1分話したら「おわる」を押してください。</p>`}
      <div class="ezd-acts" id="ezActs"><button class="ds-btn-gold" type="button" id="ezSpGo">${ico("mic")}1分スタート</button></div>
      <div class="ezd-sub"><button class="btn ghost sm2" type="button" id="ezModel">${ico("play", "fill")}お手本</button><button class="btn ghost sm2" type="button" id="ezEn">英語を見る</button></div>
      <p class="pen" id="ezEnT" hidden>${esc(src.p.en)}</p>
      ${!ezVaWeekHas() && !(ME && ME.viewer) ? `<p class="ezd-rec">${ico("mic")}今週はじめての1分スピーチ。この声を「声のアルバム」にとっておきます（このスマホの中だけ）</p>` : ""}</div>`;
  $("ezModel").addEventListener("click", () => { hush(); speak(src.p.en, src.h); });
  $("ezEn").addEventListener("click", e => { const t = $("ezEnT"); t.hidden = !t.hidden; e.currentTarget.textContent = t.hidden ? "英語を見る" : "英語をかくす"; });
  const go = () => {
    if (EZSP){ ezSpFinish(true); return; }
    hush(); ezSpStart({st, m, src, key, last, Cc});
    $("ezActs").innerHTML = `<button class="ds-btn-gold is-stop" type="button" id="ezSpGo">${ico("pause")}おわる</button>`;
    $("ezSpGo").addEventListener("click", go);
  };
  $("ezSpGo").addEventListener("click", go);
}
async function ezSpStart(o){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition, X = EZSP = {...o, t0: Date.now(), fin: "", mid: "", words: 0, on: true, err: "", parts: [], peaks: [], run: ++EZRUN};
  const upd = () => { const w = $("ezW"); if (w && EZSP === X) w.textContent = X.words = ezWordsOf(X.fin + " " + X.mid); };
  if (SR){
    const start = () => {
      const r = new SR(); r.lang = "en-US"; r.continuous = true; r.interimResults = true; r.maxAlternatives = 1;
      r.onresult = e => { let mid = ""; for (let i = e.resultIndex; i < e.results.length; i++){ const t = e.results[i][0].transcript; if (e.results[i].isFinal) X.fin += " " + t; else mid += " " + t; } X.mid = mid; upd(); };
      r.onerror = e => { X.err = e.error || "error"; };
      // 切れたらつなぎなおす（iPhone は無音で止まる・録音を始めた瞬間に止まることがある）。許可がないときと、つなぎなおしすぎのときはやめる
      r.onend = () => { X.fin += " " + X.mid; X.mid = ""; upd(); if (EZSP === X && X.on && !/not-allowed|service-not-allowed/.test(X.err) && (X.re = (X.re || 0) + 1) < 40){ X.err = ""; setTimeout(() => { if (EZSP === X && X.on) try { start(); } catch (e) {} }, 150); } else if (X.stopCb) X.stopCb(); };
      X.sr = r; try { r.start(); } catch (e) { X.err = "start"; }
    };
    start();
  }
  // 声のアルバム：この週にまだ1本もなければ、この1回を録る（MediaRecorder・この端末だけ）
  if (!ezVaWeekHas() && !(ME && ME.viewer) && window.MediaRecorder && navigator.mediaDevices){
    try {
      const stream = await navigator.mediaDevices.getUserMedia({audio: {echoCancellation: true, noiseSuppression: true}});
      if (EZSP !== X){ stream.getTracks().forEach(t => t.stop()); return; }
      const mime = ["audio/mp4", "audio/webm;codecs=opus", "audio/webm"].find(t => MediaRecorder.isTypeSupported(t)) || "";
      const rec = new MediaRecorder(stream, mime ? {mimeType: mime} : {});
      rec.ondataavailable = e => e.data && e.data.size && X.parts.push(e.data);
      X.rec = rec; X.stream = stream; X.mime = rec.mimeType || mime || "audio/mp4";
      try { const ctx = X.ctx = new (window.AudioContext || window.webkitAudioContext)(); const an = X.an = ctx.createAnalyser(); an.fftSize = 512; ctx.createMediaStreamSource(stream).connect(an); } catch (e) {}
      rec.start(1000);
    } catch (e) { X.recErr = String(e && e.name || e); }
  }
  X.iv = setInterval(() => {
    if (EZSP !== X) return clearInterval(X.iv);
    const el = (Date.now() - X.t0) / 1000, left = Math.max(0, EZ_SP_SEC - el), r = $("ezRing"), s = $("ezSec");
    if (s) s.textContent = Math.ceil(left); if (r) r.style.strokeDashoffset = String(X.Cc * (1 - left / EZ_SP_SEC));
    const ord = $("ezOrder"); if (ord){ const c = el % 12; ord.classList.toggle("dim", c >= 5 && c < 8); ord.classList.toggle("hide", c >= 8); }
    if (X.an){ const d = new Float32Array(X.an.fftSize); X.an.getFloatTimeDomainData(d); let q = 0; for (const v of d) q += v * v; X.peaks.push(Math.sqrt(q / d.length)); }
    if (left <= 0) ezSpFinish(true);
  }, 250);
}
// 録音とマイクを止める（save=false：保存しない＝画面を離れた）
function ezSpAbort(){ if (EZSP) ezSpFinish(false); }
function ezSpFinish(save){
  const X = EZSP; if (!X) return; EZSP = null; X.on = false; clearInterval(X.iv);
  const sec = Math.min(EZ_SP_SEC, Math.round((Date.now() - X.t0) / 1000));
  const stopRec = () => new Promise(res => { if (!X.rec || X.rec.state === "inactive") return res(); X.rec.onstop = () => res(); try { X.rec.stop(); } catch (e) { res(); } });
  const done = async () => {
    await stopRec();
    try { X.stream && X.stream.getTracks().forEach(t => t.stop()); } catch (e) {}
    try { X.ctx && X.ctx.close(); } catch (e) {}
    if (!save) return;
    const words = ezWordsOf(X.fin + " " + X.mid), st = X.st, m = X.m;
    ezWordsAdd(words, "speech");
    const l = ezSpLog(); l.push({t: Date.now(), k: X.key, m: m.id, w: words, sec}); store(EZSP_KEY, JSON.stringify(l.slice(-500)));
    const dl = drillLog(); dl.push({t: Date.now(), reps: 1, sec}); store("kz-drill", JSON.stringify(dl.slice(-1000)));   // 1分感情スピーキングの記録にも入れる（連続日数・練習した日）
    if (apiOn()) api("/api/log", {kind: "drill", reps: 1, sec}).catch(() => {});
    const cur = ezDay(); cur.sp = [...(cur.sp || []), words]; cur.w.sp = (+cur.w.sp || 0) + words;
    // 声のアルバムに保存（その週の最初の1回だけ・10秒以上）
    if (X.parts.length && sec >= 10 && !ezVaWeekHas()){
      const id = "v" + Date.now().toString(36), blob = new Blob(X.parts, {type: X.mime}), pk = X.peaks, mx = Math.max(0.02, ...pk);
      const peaks = [...Array(40)].map((_, i) => { const a = pk.slice(Math.floor(i * pk.length / 40), Math.max(Math.floor(i * pk.length / 40) + 1, Math.floor((i + 1) * pk.length / 40))); return a.length ? Math.round(Math.max(...a) / mx * 100) / 100 : 0; });
      try { await ezVaPut(id, blob); const A = ezJ(EZVA_KEY); A.push({id, t: Date.now(), wk: weekStart(dayKey(Date.now())), w: words, sec, topic: ezNetaLabel(m), m: m.id, title: String(m.title || "").slice(0, 40), peaks}); store(EZVA_KEY, JSON.stringify(A.slice(-120))); cur.rec = id; }
      catch (e) { console.warn("声のアルバムに保存できませんでした", e); }
    }
    ezDaySave(cur);
    // 結果を出す（前回との差）
    const w = $("ezW"), wd = $("ezWd"), acts = $("ezActs");
    if (w) w.textContent = words;
    if (wd) wd.innerHTML = X.last != null && words > 0 ? (words > X.last ? `前回より <b class="num">+${words - X.last}</b>語` : words === X.last ? "前回と同じ語数" : `前回 ${X.last}語`) : words > 0 ? "はじめての記録" : (X.sr ? "声が聞き取れませんでした。マイクの許可を確かめて、もう一度どうぞ" : "");
    if (wd) wd.classList.toggle("up", X.last != null && words > X.last);
    if (acts && KZ === "daily"){
      acts.innerHTML = `<button class="ds-btn-gold" type="button" id="ezSpNext">できた！ 次へ</button><button class="btn ghost" type="button" id="ezSpAgain">もう一度</button>`;
      $("ezSpNext").addEventListener("click", () => ezNext());
      $("ezSpAgain").addEventListener("click", () => renderDaily());
      if (cur.rec && X.parts.length) toast("今週の声を、声のアルバムにとっておきました");
    }
  };
  if (X.sr && save){ X.stopCb = () => { X.stopCb = null; done(); }; try { X.sr.stop(); } catch (e) { X.stopCb(); } setTimeout(() => { if (X.stopCb) X.stopCb(); }, 1200); }   // 最後の言葉の認識を少し待つ
  else { try { X.sr && X.sr.abort(); } catch (e) {} done(); }
}
// ③ AIと声だけで3往復（今のAI英会話を、顔なし・短く。3往復で終わり）
function ezStepAi(st, m){
  const b = $("ezdBody"), ph = ezMissionPh(m);
  b.innerHTML = `<p class="ezd-lead">今日の台本「${esc(m.title)}」の話題で、AIと声だけで<b>3往復</b>。相手から話しかけてきます。今日のフレーズを1つでも使えたらチェックがつきます。</p>
    <div class="ezd-mis">${ezMissionChips(m, "ezd-chk")}</div>
    <img class="ezd-pic" src="${esc(kzScene(m))}" alt="" loading="lazy" onerror="this.remove()">
    <button class="ds-btn-gold ezd-next" type="button" id="ezAiGo">${ico("mic")}<span>声だけで話す<small>3往復・約3分</small></span></button>
    <button class="more ezd-skip" type="button" id="ezAiSkip">今日はAIなしで終える</button>
    <p class="mapnote" id="tkNote">${apiOn() ? "マイクを使います。週のAI会話の持ち時間から使います。" : esc(noApiMsg())}</p>`;
  $("ezAiGo").addEventListener("click", () => ezTalkGo({face: false, turns: 3, daily: true}));
  $("ezAiSkip").addEventListener("click", () => ezNext({aiSkip: 1}));
  if (!ph.length) b.querySelector(".ezd-mis").remove();
}
// ③'（3分コース）2秒応答×3：教材の質問（なければ短い質問）に、2秒以内に話しはじめる
const EZ_RXQ = [["What do you like to do on weekends?", "週末は何をするのが好き？"], ["Tell me about your hometown.", "地元のことを教えて。"], ["Why are you learning English?", "なぜ英語を勉強しているの？"]];
function ezStepRx(st, m){
  const b = $("ezdBody"), qa = (m.qa || []).slice(0, 3), A = kzA(m), qs = qa.length >= 3 ? qa.map((q, i) => ({q: q.q, ja: q.q_ja || "", a: q.a, h: ((A.qa || [])[i] || [])[0]})) : EZ_RXQ.map(([q, ja]) => ({q, ja}));
  let i = 0; const times = [];
  kzTtsPrefetch(qs.map(q => [q.q, q.h]));                               // 質問の Grok の声を先に（2026-11-07・2秒応答は間があくと練習にならない）
  const show = async () => {
    if (i >= qs.length){
      rxStop();
      const got = times.filter(x => x != null), avg = got.length ? got.reduce((s, x) => s + x, 0) / got.length / 1000 : null;
      const cur = ezDay(); cur.rx = times; ezDaySave(cur);
      b.innerHTML = `<div class="ezd-cnt"><span>平均の返事の速さ</span><b class="num">${avg != null ? avg.toFixed(1) : "—"}</b><small>秒</small><em>${times.filter(x => x != null && x <= KZ_REPLY_SEC * 1000).length} / ${qs.length} 問が2秒以内</em></div>
        <button class="ds-btn-gold ezd-next" type="button" id="ezRxNext">できた！ 次へ</button>`;
      $("ezRxNext").addEventListener("click", () => ezNext()); return;
    }
    const q = qs[i], run = ++KZ_SPEAK;
    b.innerHTML = `<span class="num rpn">Q${i + 1} / ${qs.length}</span><p class="rpq">${esc(q.q)}</p><p class="rpqj">${esc(q.ja || "")}</p>
      <div class="rpring"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="34" class="bg"/><circle cx="40" cy="40" r="34" class="fg" id="rpFg"/></svg><b class="num" id="rpS">${KZ_REPLY_SEC}</b></div>
      <div class="acts" style="justify-content:center"><button class="btn big" type="button" id="rpTap" disabled>話しはじめた！</button></div><p class="rpres" id="rpRes" hidden></p>
      <div class="acts" id="rpBtns" hidden style="justify-content:center"><button class="btn" type="button" id="rpOk">次の質問</button></div>`;
    await speak(q.q, q.h, {rate: 1, wait: 1500}); if (run !== KZ_SPEAK) return;   // 声が1.5秒で間に合わなければ端末の読み上げ
    await wait(120); if (run !== KZ_SPEAK) return;
    const fg = $("rpFg"); fg.style.transition = `stroke-dashoffset ${KZ_REPLY_SEC}s linear`; void fg.getBoundingClientRect(); fg.style.strokeDashoffset = "0";
    const tap = $("rpTap"); tap.disabled = false;
    const ms = await waitReaction(run, tap);
    if (ms === undefined) return;
    times.push(ms == null ? null : Math.round(ms));
    const l = reactLog(); l.push({t: Date.now(), id: m.id, q: i, ms: ms == null ? null : Math.round(ms), mic: !!RX}); store("kz-react", JSON.stringify(l.slice(-2000)));
    if (apiOn()) api("/api/log", {kind: "react", ms: ms == null ? null : Math.round(ms), material: m.title}).catch(() => {});
    tap.hidden = true; fg.style.transition = "none";
    const r = $("rpRes"); r.hidden = false;
    r.innerHTML = ms == null ? "5秒たちました。まずは短く一言から！" : `<b class="num">${(ms / 1000).toFixed(1)}</b>秒で話しはじめました ${ms <= KZ_REPLY_SEC * 1000 ? '<span class="good">◎ 2秒以内</span>' : "<span>あと少し</span>"}`;
    $("rpBtns").hidden = false; $("rpOk").textContent = i + 1 < qs.length ? "次の質問" : "結果を見る";
    $("rpOk").addEventListener("click", () => { hush(); i++; show(); });
  };
  b.innerHTML = `<p class="ezd-lead">質問が読み上げられたら、2秒以内に声で答えはじめます。話しはじめたら「話しはじめた！」を押します。</p>
    <label class="kzchk"><input type="checkbox" id="ezRxMic" ${store("kz-react-mic") === "1" ? "checked" : ""}>マイクで自動計測（声を出したら止まる。録音はしません）</label>
    <button class="ds-btn-gold ezd-next" type="button" id="ezRxGo">${ico("play", "fill")}はじめる</button>`;
  $("ezRxMic").addEventListener("change", e => store("kz-react-mic", e.target.checked ? "1" : null));
  $("ezRxGo").addEventListener("click", async () => { if ($("ezRxMic").checked){ try { await rxStart(); } catch (e) { store("kz-react-mic", null); } } show(); });
}

/* ---------- AI会話を始める（トップのカード・今日の10分のステップ3・終わった画面から） ----------
   今のAI英会話の準備の画面を、今日の台本を選んだ状態で開き、そのまま「始める」を押す（顔あり／声だけ・3往復で終わる・ミッション）。
   準備の画面の「始める」が使う設定（EZ_TALK）は1回だけ。保存している本人の設定（顔を出す・練習のしかた）は変えない */
let EZ_TALK = null;
function ezTalkGo(o){
  const m = ezLesson();
  if (!m){ toast("台本ができるとAI英会話ができます"); return; }
  if (!apiOn()){ toast(noApiMsg()); return; }
  if (!talkMine().some(x => x.id === m.id)){ toast("この台本ではAI会話を始められません。英語＞AI英会話から選んでください"); return; }
  const ph = ezMissionPh(m), x = TALKCFG(); x.lesson = m.id; store("kz-talkcfg", JSON.stringify(x));
  EZ_TALK = {face: !!o.face, mode: "chat", goal: (o.turns ? `${o.turns}往復だけの短いウォームアップの会話。短い質問を1つずつしてください。` : "") + (ph.length ? `今日の表現を使わせてあげてください：${ph.join(" / ")}` : ""),
    ez: {turns: o.turns || 0, daily: !!o.daily, mission: ph, lesson: m.id}};
  ezStop(); TKMAKE = false; quiet(); KZ = "talk"; renderKz(); window.scrollTo(0, 0);
  const go = $("tkGo");
  if (go && !go.disabled) go.click(); else EZ_TALK = null;
}
// AI会話の画面のミッション欄（talkStart が出す）
function ezTalkMisHtml(ez){
  if (!ez || !(ez.mission || []).length) return "";
  const m = ezLesson();
  return `<div class="ez-mis" id="ezMis"><span class="ez-mis-h">${ez.turns ? `<b class="num" id="ezTurns">0 / ${ez.turns}</b>往復・` : ""}今日のミッション</span><div class="ez-mis-l">${ezMissionChips(m, "ezd-chk")}</div></div>`;
}
const ezYouTurns = T => (T.tr || []).filter(x => x.who === "you" && ezWordsOf(x.text) > 0).length;
// 文字起こしが届くたび（talkCap）：ミッションのチェックと往復の数
function ezTalkCap(){
  if (!TK || !TK.cfg.ez) return;
  ezMissionCheck(TK.tr);
  const el = $("ezTurns"); if (el && TK.cfg.ez.turns) el.textContent = `${Math.min(TK.cfg.ez.turns, ezYouTurns(TK))} / ${TK.cfg.ez.turns}`;
}
// 相手が話し終えたとき（turnComplete）：3往復（自分が3回話して、相手が返した）で終わる。相手の声が鳴り終わってから
function ezTurnDone(){
  const T = TK; if (!T || !T.cfg.ez || !T.cfg.ez.turns || T.ezEnd) return;
  const last = T.tr[T.tr.length - 1];
  if (ezYouTurns(T) < T.cfg.ez.turns || !last || last.who !== "partner") return;
  T.ezEnd = true;
  const left = T.ctx ? Math.max(0, (T.playHead - T.ctx.currentTime) * 1000) : 0;
  setTimeout(() => { if (TK === T) talkEnd(true); }, Math.min(8000, left + 900));
}
// 今日の10分のステップ3が終わったとき（talkEnd から）：終わった画面へすぐ。ふりかえり（5つの力）は後ろで作って、届いたら画面を更新
function ezDailyTalkEnd(T, seconds){
  const st = ezDay(), youW = ezWordsOf((T.tr || []).filter(x => x.who === "you").map(x => x.text).join(" "));
  st.talk = {s: seconds, w: youW}; st.w.talk = (+st.w.talk || 0) + youW;
  const C = ezSteps(st); if (C[st.step] && C[st.step].k === "ai"){ st.step = C.length; st.done = true; st.doneT = Date.now(); }
  st.rev = youW >= 5 ? "wait" : ""; ezDaySave(st);
  KZ = "daily"; renderKz(); window.scrollTo(0, 0);
  if (youW < 5) return;
  const L = T.cfg.lesson;
  api("/api/review", {transcript: T.tr, scene: T.cfg.place_text || T.cfg.place, mode: T.cfg.mode, level: T.cfg.level, theme: T.cfg.theme, partner: T.cfg.partner, seconds, ...(L ? {lesson: {id: L.id, title: L.title, phrases: L.phrases}} : {})})
    .then(r => {
      if (r && !r.empty){
        const tg = L ? talkTargets(r, L, T.tr) : null, l = talkLog();
        l.push({t: Date.now(), seconds, words: r.words || 0, place: T.cfg.place, partner: T.cfg.partner, score: talkScore(r.score), ...(talkSteps(r.steps) ? {steps: talkSteps(r.steps)} : {}), fixes: (r.fixes || []).length,
          types: r.mistake_types || [], can: r.can_do || [], daily: 1, ...(L ? {lesson: L.id, used: tg.filter(x => x.used).length, of: tg.length} : {})});
        store("kz-talks", JSON.stringify(l.slice(-300)));
        if (typeof cdStamp === "function") cdStamp();
      }
      const s2 = ezDay(); s2.rev = "ok"; ezDaySave(s2);
    })
    .catch(() => { const s2 = ezDay(); s2.rev = "ng"; ezDaySave(s2); })
    .finally(() => { if (KZ === "daily" && $("ezUp")) $("ezUp").outerHTML = ezUpHtml(); });
}

/* ---------- 終わった画面 ---------- */
function ezUpHtml(){
  const st = ezDay(), now = ezPowers(null), p0 = st.pw0 || {};
  const ups = now.filter(a => a.p != null && p0[a.k] != null && a.p > p0[a.k]), news = now.filter(a => a.p != null && p0[a.k] == null);
  const rxBest = (() => { const v = reactLog().filter(x => x && x.ms > 0 && x.t >= new Date(st.d + "T00:00:00").getTime()).map(x => x.ms); return v.length ? Math.min(...v) : null; })();
  const pb = rxBest != null && (st.rx0 == null || rxBest < st.rx0);
  const lines = [...ups.map(a => `<li><b>${esc(a.ja)} ${p0[a.k]} → ${a.p}</b></li>`), ...news.map(a => `<li><b>${esc(a.ja)}力 ${a.p}</b><span>はじめて測れました</span></li>`), ...(pb ? [`<li><b>返事 ${(rxBest / 1000).toFixed(1)}秒</b><span>自己ベスト！</span></li>`] : [])];
  const wait = st.rev === "wait";
  return `<div class="ezd-card ezd-up" id="ezUp"><h4>${lines.length ? "ステータスUP！" : "今日の積み上げ"}</h4>
    ${lines.length ? `<ul>${lines.join("")}</ul>${ups.length ? `<p class="s">五角形がちょっと大きくなった！</p>` : ""}` : `<p class="s">${wait ? "AIのふりかえりで、5つの力を計算しています…" : "今日の練習は記録しました。続けるほど、五角形が育っていきます。"}</p>`}
    ${wait && lines.length ? `<p class="s">AIのふりかえりを計算しています…</p>` : ""}</div>`;
}
function ezDoneRender(){
  const box = $("kzwrap"), st = ezDay(), W = ezWords(), today = ezWordsToday(), C = EZ_COURSE[st.course];
  const next = EZ_BADGES.find(b => b > W.total), prevB = [...EZ_BADGES].reverse().find(b => b <= W.total) || 0, pr = next ? Math.round(100 * (W.total - prevB) / (next - prevB)) : 100;
  let run = 0; try { if (ME) run = skOf(ME).run; } catch (e) {}
  const v = st.rec ? ezAlbum().find(x => x.id === st.rec) : null, wkHas = ezVaWeekHas();
  box.innerHTML = `<button class="more kzback" type="button" id="ezdBack">← 英語のトップへ</button>
    <div class="ezd ezd-done">
      <div class="ezd-bar"><b>今日の${C.min}分 クリア</b>${run ? `<span class="ezd-chip ok">${run}日目</span>` : ""}</div>
      <div class="ezd-card ezd-big"><span>今日しゃべった英語</span><b class="num" data-ezc="${today}">${today}</b><small>語</small>
        <p>これまでの合計 <b class="num">${ezFmt(W.total)}語</b></p>
        <span class="ezd-bdg" aria-hidden="true"><i style="width:${pr}%"></i></span>
        <p class="s">${next ? `あと <b class="num">${ezFmt(next - W.total)}</b>語 で「${ezFmt(next)}語」バッジ` : "最高のバッジまで到達！"}</p></div>
      ${v ? `<div class="ezd-card ezd-voice"><h4>今日の声、とっておきました</h4><div class="ez-va-row"><button type="button" class="ez-va-p hot" data-vap="${esc(v.id)}" aria-label="今日の声を聞く"></button><span class="ez-va-w" aria-hidden="true">${ezWave(v.peaks, 24)}</span><span class="ez-va-d">${v.w}語</span></div><p class="s">初日の声と聴き比べると、ちがいが耳でわかります（英語のトップの「声のアルバム」）</p></div>`
        : wkHas ? `<div class="ezd-card ezd-voice"><h4>今週の声は、もうとってあります</h4><p class="s">声のアルバムには週に1本。来週の1分スピーチの声が、次の1本になります。</p></div>` : ""}
      ${ezUpHtml()}
      ${apiOn() ? `<button class="ds-btn-gold ezd-next" type="button" id="ezMore">${ico("chat")}<span>このままAIと話す<small>ミッション付き</small></span></button>` : `<button class="ds-btn-gold ezd-next" type="button" data-demo>${ico("chat")}<span>このままAIと話す<small>ミッション付き</small></span></button>`}
      <button class="btn ghost ezd-home" type="button" id="ezHome">英語のトップへ</button></div>`;
  ezCount(box);
  const home = () => { ezStop(); quiet(); KZ = null; renderKz(); window.scrollTo(0, 0); };
  $("ezdBack").addEventListener("click", home); $("ezHome").addEventListener("click", home);
  if ($("ezMore")) $("ezMore").addEventListener("click", () => ezTalkGo({face: avOn()}));
  box.querySelectorAll("[data-vap]").forEach(b => b.addEventListener("click", () => ezVaPlay(b)));
}

/* ---------- ステータスのくわしい画面（KZ="status"）：前のトップの主役（大きな五角形・はしご・実戦の記録）と数字・ふりかえり ---------- */
function renderKzStatus(){
  const box = $("kzwrap"), S = ezStats(), rowB = (k, w, t, d, a) => `<button type="button" class="ds-row tap" ${a}>${cover(k, w, {size: "xs"})}<span><b>${t}</b><span class="ds-meta"><span>${d}</span></span></span>${EZ_CHEV}</button>`;
  box.innerHTML = `${ezHeroHtml()}
    <div class="ez-stats ds-stats is-4">
      <div class="ds-stat"><small>今週</small><b>${ezNum(S.wdays, 0, "i")}<span>/7日</span></b></div>
      <div class="ds-stat"><small>覚えた単語</small><b>${ezNum(S.learned, 0, "i")}<span>語</span></b></div>
      <div class="ds-stat"><small>教材</small><b>${ezNum(S.mats, 0, "i")}<span>本</span></b></div>
      <div class="ds-stat"><small>AI会話</small><b>${ezNum(S.talks, 0, "i")}<span>回</span></b></div></div>
    <div class="sec-head"><h2>ふりかえり</h2></div>
    ${rowB("news", "Data", "くわしい記録", "グラフ・よく出る間違い・言えるようになった表現", `data-ez="records"`)}
    ${rowB("quest", "Month", "月のふりかえり", "この1か月の伸び", `data-mr="${mrMonth()}"`)}`;
  bindCommon(box); ezCount(box); ezRealBind(box);
  box.querySelectorAll("[data-kq]").forEach(b => b.addEventListener("click", () => kzQuick(b.dataset.kq)));
  box.querySelectorAll("[data-ez]").forEach(b => b.addEventListener("click", () => ezGo(b.dataset.ez)));
}
// テスト用の口（tools/shot_english_daily.mjs）。読み書きするのはこの端末の記録と画面だけ
window.__cgDaily = {kz: () => KZ, home: () => { showTab("kz"); KZ = null; renderKz(); window.scrollTo(0, 0); }, sched: ev => { if (ME){ ME.schedule = [...(ME.schedule || []), ev]; } renderKz(); },
  mission: tr => ezMissionCheck(tr), sp: () => EZSP, day: () => ezDay(), daySave: o => ezDaySave(o), words: (n, s) => ezWordsAdd(n, s), renderDaily: () => renderDaily(), render: () => renderKz()};

/* ================= はじめの1週間ガイド（登録後のオンボーディング） ================= */
/* 本人用のリンクではじめて開いた日を1日目に、7日間、1日1〜2個の小さなステップを出す（会議メモ 項目32「入会してからの流れをスムーズに」）。
   ステップはホームの「今日やること」に混ぜ、その日のステップは「今日の1つ」にいちばん先に選ばれる。全体の表はマイ＞はじめの1週間ガイド
   - はじめて開いたときだけ「ようこそ」の案内（5枚）を出す
   - ステップの「できた」は、できるものは記録から自動で判定（目標・練習・単語集・2秒応答/AI会話・クエスト）。判定できないもの（ホーム画面に追加・シェア）は本人が押す
   - その日までのステップでまだのものは「今日やること」（_part_engage.js）にも赤で出る
   - 記録はこの端末だけ（cg-ob-*）。先生リンク（見る人）には出さない。デモは3日目として見せる（端末には残さない）
   - 前から使っている人は、はじめて開いた日（cg-open-days のいちばん古い日）から数えるので、14日を過ぎていれば出ない。歯車の「はじめの1週間ガイド」でもう一度出せる */
const OB_DAYS = 7;
const obKey = k => "cg-ob-" + k + (DEMO ? "-demo" : "");
let OB_BIP = null;                                    // Android/PC の Chrome の「インストール」の合図（あれば、ボタンからそのまま出せる）
window.addEventListener("beforeinstallprompt", e => { e.preventDefault(); OB_BIP = e; });
const a2hsHow = () => isIOS() ? "Safari の共有ボタン（□に↑）→「ホーム画面に追加」。次からはアイコンで開けて、通知も使えます（iOS 16.4 以上）"
  : "ブラウザのメニュー（︙）→「ホーム画面に追加」または「アプリをインストール」。次からはアイコンで開けます";
const obSteps = () => [
  {day: 1, k: "home", t: "ホーム画面に追加する", s: a2hsHow(), btn: OB_BIP ? "インストール" : "やり方を見る", fn: obInstall, manual: true, done: () => isStandalone() || store(obKey("home")) === "1"},
  {day: 1, k: "goal", t: "今月の目標を決める", s: "目標シートに書いたことを、そのまま書けばOK", btn: "目標を書く", go: "#goal", done: d => !!goalGet(d.today.slice(0, 7))},
  {day: 2, k: "kz", t: "教材で1回練習する", s: "「語順で話す」を1段落、声に出すだけでOK。連続記録が始まります", btn: "教材を開く", tab: "kz", done: d => studyEvents().length > 0 || (d.study_days || []).length > 0},
  {day: 3, k: "word", t: "単語集に1つ入れる", s: "教材の英文で、覚えたい単語をタップ →「単語集に入れる」。1・3・7日後に復習が出ます", btn: "教材を開く", tab: "kz", done: () => wdList().length > 0},
  {day: 4, k: "react", t: "2秒応答かAI会話を1回やってみる", s: "質問に2秒以内に答える練習。答えの速さが記録されます", btn: "教材を開く", tab: "kz", done: () => reactLog().length > 0 || talkLog().length > 0},
  {day: 5, k: "quest", t: "ひとりクエストを1つクリア", s: "外国の方に会いに行く小さな冒険。見つけて予定に入れるだけのものもあります", btn: "クエストを見る", tab: "quest",
    done: () => { try { return Object.keys(localStorage).some(k => k.startsWith("quest-") && localStorage.getItem(k) === "1"); } catch (e) { return false; } }},
  {day: 6, k: "share", t: "共有部屋で自己紹介・気づきをシェア", s: "Discord の「学び・気づきの共有部屋」に一言。+" + ALL.rules.pts.share + "pt。仲間からコメントが届きます", btn: "共有部屋を開く",
    url: (ALL.links || {}).manabi, manual: true, done: d => ((d.cnt.all || {}).share || 0) > 0 || store(obKey("share")) === "1"},
  {day: 7, k: "remind", t: "リマインドの時刻を決める", s: "まだの項目があったら、決めた時刻に知らせます（右上の歯車 →「リマインド・通知」）", btn: "設定を開く", fn: obRemind, done: () => !!store("cg-remind")}
];
function obInstall(){
  if (OB_BIP){ OB_BIP.prompt(); OB_BIP.userChoice.then(r => { if (r.outcome === "accepted"){ store(obKey("home"), "1"); renderMeKeep(); } }).catch(() => {}); OB_BIP = null; return; }
  toast(a2hsHow(), 6500);
}
function obRemind(){ $("setPanel").hidden = false; $("gear").setAttribute("aria-expanded", "true"); remRender(); obSetRender(); if (typeof spkSetRender === "function") spkSetRender(); if (typeof chPrefsRender === "function") chPrefsRender(); }   // 設定は全画面で開く（_part_settings.js）ので、ページを上まで動かさない（閉じたら元の位置に戻る）
function obStart(){
  const today = dayKey(Date.now());
  if (DEMO){ const t = new Date(today + "T12:00:00"); t.setDate(t.getDate() - 2); return dayKey(t); }
  let s = store("cg-ob-start");
  if (!s){ s = openDays()[0] || today; store("cg-ob-start", s); }
  return s;
}
const obDay = () => Math.floor((new Date(dayKey(Date.now()) + "T12:00:00") - new Date(obStart() + "T12:00:00")) / 864e5) + 1;
function obOn(d){
  if (!d || d.viewer || store(obKey("hide")) === "1") return false;
  return obDay() <= OB_DAYS * 2 || store(obKey("show")) === "1";   // 1週間がすぎても、まだのものがあれば2週目まで出す
}
// 「今日やること」に入れる分：今日までのステップでまだのもの（目標・練習は今日やることに元からあるので入れない）
function obItems(d){
  if (!obOn(d)) return [];
  const day = Math.min(obDay(), OB_DAYS);
  return obSteps().filter(x => x.day <= day && x.k !== "goal" && x.k !== "kz" && !x.done(d)).map(x => ({k: "ob-" + x.k, t: "ガイド：" + x.t, s: x.day + "日目のステップ", tab: x.tab, url: x.url, go: x.go || "#obCard", fn: x.fn, done: false}));
}
function obHtml(d){
  if (!obOn(d)) return "";
  const st = obSteps(), day = obDay(), cur = Math.min(day, OB_DAYS), nd = st.filter(x => x.done(d)).length, all = nd === st.length;
  const dayDone = n => st.filter(x => x.day === n).every(x => x.done(d));
  return `<section class="obcard${all ? " clear" : ""}" id="obCard" aria-label="はじめの1週間ガイド">
    <div class="ob-h"><span class="gl-k">はじめの1週間ガイド</span><b>${all ? "ぜんぶクリア！" : day > OB_DAYS ? "のこりのステップ" : `${cur}日目`}</b><span class="num ob-n">${nd} / ${st.length}</span></div>
    <div class="ob-days" aria-hidden="true">${[...Array(OB_DAYS)].map((_, i) => `<i class="${dayDone(i + 1) ? "on" : ""}${i + 1 === cur ? " now" : ""}${i + 1 > cur ? " fut" : ""}">${dayDone(i + 1) ? "✓" : i + 1}</i>`).join("")}</div>
    <p class="mini">${all ? "1週間のステップを、ぜんぶやりきりました。ここからは「今日やること」を毎日0にしていきましょう。" : "1日1〜2個の小さなステップです。先の日の分を先にやってもOK。"}</p>
    <ol class="oblist">${st.map((x, i) => { const ok = x.done(d), cls = ok ? "ok" : x.day <= cur ? "due" : "later";
      return `<li class="${cls}"><span class="ob-d">${x.day}日目</span><div><b>${esc(x.t)}</b><small>${esc(x.s)}</small>
        ${ok ? "" : `<div class="acts">${x.url ? `<a class="btn sm2" href="${esc(x.url)}" target="_blank" rel="noopener">${ICON.ext}${esc(x.btn)}</a>` : `<button type="button" class="btn sm2" data-obgo="${i}">${esc(x.btn)}</button>`}${x.manual ? `<button type="button" class="btn ghost sm2" data-obdone="${x.k}">できた</button>` : ""}</div>`}</div>
        <em>${ok ? "✓" : x.day <= cur ? "まだ" : "これから"}</em></li>`; }).join("")}</ol>
    <div class="acts"><button type="button" class="more" id="obHide">${all ? "ガイドを閉じる" : "ガイドを閉じる（歯車からまた出せます）"}</button></div></section>`;
}
function renderMeKeep(){ if (!ME) return; const y = window.scrollY; renderMe(ME); window.scrollTo(0, y); }
function bindOb(){
  const c = $("obCard"); if (!c) return;
  const st = obSteps();
  c.querySelectorAll("[data-obgo]").forEach(b => b.addEventListener("click", () => engGo(st[+b.dataset.obgo])));
  c.querySelectorAll("[data-obdone]").forEach(b => b.addEventListener("click", () => { store(obKey(b.dataset.obdone), "1"); toast("ナイス！ステップをクリアしました"); renderMeKeep(); }));
  $("obHide").addEventListener("click", () => { store(obKey("hide"), "1"); store(obKey("show"), null); renderMeKeep(); toast("ガイドを閉じました。歯車の「はじめの1週間ガイド」から、また出せます"); });
}
// 歯車の中：ガイドをもう一度出す
function obSetRender(){
  const box = $("spGuide"); if (!box) return;
  if (!ME || ME.viewer){ box.hidden = true; return; }
  box.hidden = false;
  box.innerHTML = `<b>はじめの1週間ガイド</b><div class="acts"><button type="button" class="btn ghost sm2" id="obAgain">ガイドを開く</button><button type="button" class="btn ghost sm2" id="obTour">「ようこそ」の案内を見る</button></div>`;
  $("obAgain").addEventListener("click", () => { store(obKey("hide"), null); store(obKey("show"), "1"); stHide(); renderMeKeep(); myGo("guide"); });   // 設定の全画面はすぐ閉じる（_part_settings.js）
  $("obTour").addEventListener("click", () => { stHide(); obWelcome(true); });
}

