const pvLocalOk = () => store("cg-pv") === PV_VER;
const pvAgreed = () => PV.state === true || (PV.state === null && pvLocalOk());   // 中継を知らないとき（古い中継・電波なし）は端末の控えで
function pvWait(){ try { return PV.posting || Promise.resolve(); } catch (e) { return Promise.resolve(); } }   // 同意を送っている途中は、AI の呼び出しを待たせる（順番が逆にならないように）。api() から同期で呼ぶので関数宣言
const pvDay = t => { const d = new Date(t || 0); return isNaN(d) ? "" : `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`; };
// 中継の同意の状態を読む（アプリを開いたとき・設定を開いたとき）。古い中継（404）・つながらないときは null のまま
async function pvRefresh(){
  if (DEMO || !apiOn() || !API_AUTH) return;
  try { const r = await api("/api/privacy/consent"); PV.state = !!r.agreed; PV.t = r.t || null; store("cg-pv", r.agreed ? PV_VER : null); }
  catch (e) {}
  pvSetRender();
}
// 同意を中継に送る（agree:false で、やめる）。古い中継（404）は端末の控えだけ
async function pvSend(agree){
  try {
    const r = await api("/api/privacy/consent", agree ? {agree: true, ver: PV_VER} : {agree: false});
    PV.state = !!r.agreed; PV.t = r.t || null; return true;
  } catch (e) {
    if (/新しく/.test(e.message)){ PV.state = false; toast("個人情報の扱いが新しくなりました。ページを読み込みなおしてから、もう一度どうぞ", 5000); return false; }
    return null;                                                 // つながらない・古い中継：端末の控えだけで進む（中継が新しくなったら、そのときもう一度聞く）
  }
}
// AI を使う前の入口（先に確かめたいところ＝インタビュー）から：同意ずみなら true、まだならシートを出して答えを待つ
function pvGate(){ return pvAgreed() ? Promise.resolve(true) : pvConsentSheet(); }
// api() が 403 {need_consent} を受けたとき：端末の控えを消して、シートを出す（同意したら api() がやり直す）
function pvOnNeed(j){ PV.state = false; store("cg-pv", null); pvSetRender(); return pvConsentSheet(); }
const PV_NO = "AIを使う機能は、「個人情報の扱い」に同意すると使えます（マイ＞設定＞個人情報の扱い から、いつでも同意できます）";

/* ---------- 下から出るシート（共通） ---------- */
function pvSheet(html, cls){
  const d = document.createElement("div"); d.className = "pv-sheet" + (cls ? " " + cls : ""); d.setAttribute("role", "dialog"); d.setAttribute("aria-modal", "true");
  d.innerHTML = `<div class="pv-sheet-in">${html}</div>`;
  document.body.appendChild(d); requestAnimationFrame(() => d.classList.add("in"));
  const close = () => { d.classList.remove("in"); setTimeout(() => d.remove(), reduce ? 0 : 260); };
  return {d, close};
}
const PV_SENDTO = [["Google", "米国", "Gemini（AI会話・添削・教材づくり・インタビュー）"], ["X.AI", "米国", "Grok（教材の音声づくり）"], ["Simli", "米国", "AI会話の相手の顔の動き（あなたの声は送りません）"], ["Cloudflare", "米国", "アプリのサーバー・記録の保存"]];
function pvConsentHtml(){
  return `<div class="pv-hero pv-hero-c"><span class="pv-orb" aria-hidden="true">${ico("shield")}</span><span class="pv-ey">AIを使う前に、1回だけ</span>
      <h2 id="pvcT">あなたの記録の扱いを、<br>確かめてください</h2><p>AIがあなたに合わせた練習を作るために、話した内容を外国のAIの会社に送ります。</p></div>
    <div class="pv-grid2">
      <section class="pv-tile pv-keep"><h3>${ico("save")}保存するもの</h3><ul><li>会話・インタビューの<b>文字起こし</b></li><li>添削・評価・わたしメモ</li><li>作った教材・日記</li></ul></section>
      <section class="pv-tile pv-drop"><h3>${ico("micoff")}保存しないもの</h3><ul><li><b>音声そのもの</b>（解析したら、その場で捨てます）</li><li>顔認証の顔のデータ</li><li>名前・メールはAIに送りません</li></ul></section>
    </div>
    <section class="pv-card"><h3 class="pv-h3">${ico("globe")}送る先（外国の会社）</h3>
      <ul class="pv-to">${PV_SENDTO.map(([n, c, w]) => `<li><b>${esc(n)}</b><span class="pv-cc">${esc(c)}</span><small>${esc(w)}</small></li>`).join("")}</ul>
      <p class="pv-note">Gemini は有料の契約で使っていて、送った内容がAIの学習に使われないことになっています。</p></section>
    <ul class="pv-promise">
      <li>${ico("check")}<span>同意しなくても、AI以外の機能（記録・単語集・みんな・ひろばなど）はそのまま使えます</span></li>
      <li>${ico("trash")}<span>記録はいつでも、マイ＞設定＞私のデータ から見る・消すことができます</span></li>
    </ul>
    <button type="button" class="pv-more" data-pvpol>${ico("doc")}「個人情報の扱い」をぜんぶ読む</button>
    <p class="pv-by">提供：チアーズメイト株式会社（個人情報の窓口 <a class="pv-a" href="mailto:info@cheersmate11.com">info@cheersmate11.com</a>）</p>
    <div class="pv-acts"><button type="button" class="ds-btn-gold tap" data-pvyes>${ico("shieldok")}同意して始める</button><button type="button" class="pv-ghost tap" data-pvno>今はやめておく</button></div>`;
}
// 同意のシート：答え（true＝同意・false＝やめる）を返す。2つ同時には出さない（同じ答えを待つ）
function pvConsentSheet(){
  if (PV.sheet) return PV.sheet;
  PV.sheet = new Promise(resolve => {
    const {d, close} = pvSheet(pvConsentHtml(), "pv-consent");
    d.setAttribute("aria-labelledby", "pvcT");
    let step2 = false;                                               // 2ページ目（学びノートを使うか・_part_ainotes.js）を出している：同意はもうすんでいる
    const done = ok => { PV.sheet = null; close(); document.removeEventListener("keydown", esc1); resolve(ok); };
    const dismiss = () => { if (step2){ anChoose(false); done(true); } else done(false); };   // 2ページ目で閉じた＝同意はした・学びノートは今はしない
    const esc1 = e => { if (e.key === "Escape") dismiss(); };
    document.addEventListener("keydown", esc1);
    d.addEventListener("click", e => { if (e.target === d) dismiss(); });
    d.querySelector("[data-pvno]").onclick = () => { done(false); toast("AIの機能は使わずに続けます。いつでも マイ＞設定 から同意できます", 4200); };
    d.querySelector("[data-pvpol]").onclick = () => pvPolicyOpen();
    d.querySelector("[data-pvyes]").onclick = () => {
      store("cg-pv", PV_VER); PV.state = true; PV.t = new Date().toISOString();
      // 同意を送るのを待たずに、このタップの中で答えを返す（マイク・音の準備はタップの中でないと iPhone で止まるため）。AI の呼び出しは pvWait() で送り終わるまで待つ
      PV.posting = pvSend(true).then(r => { if (r === false){ store("cg-pv", null); } PV.posting = null; pvSetRender(); });
      if (typeof anNeed === "function" && anNeed()){ step2 = true; anShowIn(d.querySelector(".pv-sheet-in"), () => done(true)); return; }   // 続けて「学びノート」を使うか（1回だけ）。答えのタップの中で返す
      done(true);
    };
    try { d.querySelector("[data-pvyes]").focus({preventScroll: true}); } catch (e) {}
  });
  return PV.sheet;
}

/* ---------- 全画面（設定の上に重ねる）：個人情報の扱い・私のデータ ---------- */
const PVS = {el: null, pushed: false, skip: 0};
function pvScreen(title, html){
  pvScreenClose(true);
  const el = document.createElement("div"); el.className = "pv-screen"; el.setAttribute("role", "dialog"); el.setAttribute("aria-modal", "true"); el.setAttribute("aria-label", title);
  el.innerHTML = `<div class="pv-bar"><button type="button" class="st-back" data-pvback aria-label="戻る"><svg class="st-chev" viewBox="0 0 24 24" aria-hidden="true"><path d="M15 4.5 7.5 12l7.5 7.5"/></svg><span>戻る</span></button><h1>${esc(title)}</h1><span aria-hidden="true"></span></div>
    <div class="pv-body">${html}</div>`;
  document.body.appendChild(el); PVS.el = el;
  try { history.pushState({cgpv: 1}, "", location.href); PVS.pushed = true; } catch (e) { PVS.pushed = false; }
  requestAnimationFrame(() => el.classList.add("in"));
  el.querySelector("[data-pvback]").addEventListener("click", () => pvScreenBack());
  setTimeout(() => { try { el.querySelector("[data-pvback]").focus({preventScroll: true}); } catch (e) {} }, 300);
  return el;
}
function pvScreenClose(now){
  const el = PVS.el; if (!el) return; PVS.el = null;
  if (now || reduce){ el.remove(); return; }
  el.classList.remove("in"); el.classList.add("out"); setTimeout(() => el.remove(), 280);
}
function pvScreenBack(){ if (!PVS.el) return; if (PVS.pushed){ PVS.pushed = false; PVS.skip++; history.back(); } pvScreenClose(); }
// ブラウザ／スマホの「戻る」：設定（_part_settings.js）より先に受けて、上の画面だけ閉じる
window.addEventListener("popstate", e => {
  if (PVS.skip){ PVS.skip--; e.stopImmediatePropagation(); return; }
  if (PVS.el){ PVS.pushed = false; e.stopImmediatePropagation(); pvScreenClose(); }
});
document.addEventListener("keydown", e => { if (e.key === "Escape" && PVS.el && !document.querySelector(".pv-sheet")){ e.stopImmediatePropagation(); pvScreenBack(); } }, true);

/* ---------- 個人情報の扱い（docs/privacy-policy.md を読みやすく） ---------- */
const pvInline = s => esc(s).replace(/\*\*(.+?)\*\*/g, "<b>$1</b>").replace(/【([^】]*)】/g, '<mark class="pv-todo">【$1】</mark>')
  .replace(/https:\/\/[A-Za-z0-9.\/_-]+/g, u => `<a class="pv-a" href="${u}" target="_blank" rel="noopener">${u}</a>`)   // 会社の方針のページ（esc のあとなので、URL に使う文字だけ）
  .replace(/\b([A-Za-z0-9._-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+)\b/g, '<a class="pv-a" href="mailto:$1">$1</a>');
const PV_SEC_ICO = {1: "folder", 2: "target", 3: "globe", 4: "eye", 5: "clock", 6: "lock", 7: "user", 8: "alarm", 9: "heart", 10: "mail", 11: "pencil"};
function pvDocParse(md){
  const lines = String(md || "").replace(/\r/g, "").split("\n"), out = {title: "", secs: [], lead: [], foot: []};
  let cur = null, tbl = null;
  const push = h => (cur ? cur.body : out.lead).push(h);
  const flushTbl = () => { if (!tbl) return; const [head, ...rows] = tbl; push(`<div class="pv-tbl">${rows.map(r => `<div class="pv-tr">${r.map((c, i) => `<div class="pv-td"><small>${pvInline(head[i] || "")}</small><span>${pvInline(c)}</span></div>`).join("")}</div>`).join("")}</div>`); tbl = null; };
  let list = null;
  const flushList = () => { if (!list) return; push(`<${list.t} class="pv-list">${list.items.map(x => `<li>${pvInline(x)}</li>`).join("")}</${list.t}>`); list = null; };
  for (const raw of lines){
    const l = raw.trim();
    if (/^\|/.test(l)){ flushList(); const cells = l.replace(/^\||\|$/g, "").split("|").map(x => x.trim()); if (cells.every(c => /^:?-{2,}:?$/.test(c))) continue; (tbl = tbl || []).push(cells); continue; }
    flushTbl();
    let m;
    if (/^>/.test(l)) continue;                                 // 下書きのメモ（作る人向け）はアプリに出さない
    if ((m = l.match(/^# (.+)/))){ flushList(); out.title = m[1].replace(/（下書き[^）]*）/, "").replace(/^チアーズGO!\s*/, "").trim(); continue; }
    if ((m = l.match(/^## (\d+)\.\s*(.+)/))){ flushList(); cur = {n: +m[1], t: m[2], body: []}; out.secs.push(cur); continue; }
    if ((m = l.match(/^- (.+)/))){ if (!list || list.t !== "ul"){ flushList(); list = {t: "ul", items: []}; } list.items.push(m[1]); continue; }
    if ((m = l.match(/^\d+\. (.+)/))){ if (!list || list.t !== "ol"){ flushList(); list = {t: "ol", items: []}; } list.items.push(m[1]); continue; }
    flushList();
    if (l) push(`<p>${pvInline(l)}</p>`);
  }
  flushList(); flushTbl();
  return out;
}
function pvStatusHtml(){
  if (DEMO) return `<span class="pv-chip">${ico("eye")}デモ表示中（同意はこの端末の中だけ）</span>`;
  if (pvAgreed()) return `<span class="pv-chip ok">${ico("shieldok")}同意ずみ${PV.t ? "（" + esc(pvDay(PV.t)) + "）" : ""}</span>`;
  return `<span class="pv-chip">${ico("shield")}まだ同意していません（AIの機能を使うときに聞きます）</span>`;
}
function pvPolicyHtml(){
  const P = pvDocParse(PV_DOC);
  const promises = [["micoff", "音声は保存しない", "AI会話・音読・ひろばの声は、解析したらその場で捨てます"], ["ai", "AIの学習に使わない", "有料の契約で、送った内容がAIの学習に使われないようにしています"], ["trash", "いつでも見る・消せる", "マイ＞設定＞私のデータ から、自分でダウンロード・削除できます"]];
  const canAct = !DEMO && apiOn() && API_AUTH;
  return `<section class="pv-hero"><span class="pv-orb" aria-hidden="true">${ico("shield")}</span><span class="pv-ey">チアーズGO!</span><h2>${esc(P.title || "個人情報の取り扱いについて")}</h2>
      <p>あなたの記録を、どこに・何のために・いつまで置くかをまとめました。</p><div class="pv-hero-foot">${pvStatusHtml()}<span class="pv-ver">版 ${esc(PV_VER)}</span></div></section>
    <ol class="pv-promises">${promises.map(([i, h, s], k) => `<li style="--i:${k}"><span class="pv-pi">${ico(i)}</span><div><b>${h}</b><small>${s}</small></div></li>`).join("")}</ol>
    ${P.lead.length ? `<div class="pv-lead">${P.lead.join("")}</div>` : ""}
    <div class="pv-secs">${P.secs.map((s, k) => `<details class="pv-sec" ${k < 1 ? "open" : ""} style="--i:${k}"><summary><span class="pv-num num">${s.n}</span><span class="pv-sico">${ico(PV_SEC_ICO[s.n] || "doc")}</span><b>${pvInline(s.t)}</b><svg class="pv-chev" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="pv-secb">${s.body.join("")}</div></details>`).join("")}</div>
    <div class="pv-foot-acts">
      ${pvAgreed() ? (canAct ? `<button type="button" class="pv-ghost tap" data-pvwd>同意をやめる（AIの機能を止める）</button>` : "") : `<button type="button" class="ds-btn-gold tap" data-pvagree>${ico("shieldok")}読んだうえで同意する</button>`}
      <button type="button" class="pv-link-row tap" data-pvgo="data">${ico("folder")}<span><b>私のデータ</b><small>ダウンロード・すべて消す</small></span>${ico("chevron")}</button>
    </div>`;
}
function pvPolicyOpen(){
  const el = pvScreen("個人情報の扱い", pvPolicyHtml());
  pvPolicyBind(el);
}
function pvPolicyBind(el){
  const body = el.querySelector(".pv-body");
  const repaint = () => { body.innerHTML = pvPolicyHtml(); pvPolicyBind(el); };
  const ag = el.querySelector("[data-pvagree]");
  if (ag) ag.onclick = async () => {
    store("cg-pv", PV_VER); PV.state = true; PV.t = new Date().toISOString();
    if (!DEMO && apiOn() && API_AUTH){ const r = await pvSend(true); if (r === false) store("cg-pv", null); }
    toast("同意しました。AIの機能が使えます"); repaint(); pvSetRender();
  };
  const wd = el.querySelector("[data-pvwd]");
  if (wd) wd.onclick = () => {
    const {d, close} = pvSheet(`<div class="pv-sh-ic warn">${ico("shield")}</div><h3 class="pv-sh-t">同意をやめますか？</h3>
      <p class="pv-sh-p">AI会話・インタビュー・教材づくりなど、AIを使う機能が使えなくなります。これまでの記録は消えません（消すときは「私のデータ」から）。</p>
      <div class="pv-acts"><button type="button" class="pv-danger tap" data-pvok>同意をやめる</button><button type="button" class="pv-ghost tap" data-pvx>やめない</button></div>`, "sm");
    d.addEventListener("click", e => { if (e.target === d || e.target.closest("[data-pvx]")) close(); });
    d.querySelector("[data-pvok]").onclick = async () => {
      const r = await pvSend(false); close();
      if (r === null){ toast("いまはつながりません。あとでもう一度どうぞ"); return; }
      store("cg-pv", null); PV.state = false; PV.t = null; toast("同意をやめました。AIの機能は止まっています"); repaint(); pvSetRender();
    };
  };
  el.querySelectorAll("[data-pvgo='data']").forEach(b => b.onclick = () => pvDataOpen());
}

/* ---------- 私のデータ（見る・消す） ---------- */
const PV_KEEP_LOCAL = ["cg-token", "cg-theme", "cg-accent", "cg-tab", "cg-ob-welcome", "cg-ob-welcome-demo"];   // すべて消したあとも端末に残すもの（リンク・表示の設定だけ）
const pvLocalDump = () => { const o = {}; try { for (let i = 0; i < localStorage.length; i++){ const k = localStorage.key(i); if (!k || /token|key|sync-sent|^cg-dev$/i.test(k)) continue; const v = localStorage.getItem(k); try { o[k] = JSON.parse(v); } catch (e) { o[k] = v; } } } catch (e) {} return o; };
const PV_DEL_LIST = [["chat", "AI会話・インタビューの文字起こしと添削、音読チェック、英語日記"], ["book", "作った教材・単語集・今月の目標・わたしメモ（ほかの端末と同期した分）"], ["users", "投稿・乾杯・チャンネルのメッセージ（「削除されました」になります）・名鑑のプロフィールと写真"],
  ["handshake", "乾杯バディ・ひろばの予約・リーグ・ごほうびの記録"], ["bell", "通知の登録・パスキー"], ["shield", "個人情報の扱いへの同意・学びノートの設定とまとめ（次にAIを使うときに、もう一度聞きます）"]];
function pvDataHtml(){
  const canAct = !DEMO && apiOn() && API_AUTH;
  const n = (() => { try { return Object.keys(pvLocalDump()).length; } catch (e) { return 0; } })();
  return `<section class="pv-hero pv-hero-d"><span class="pv-orb" aria-hidden="true">${ico("folder")}</span><span class="pv-ey">私のデータ</span><h2>あなたの記録は、<br>あなたのもの</h2>
      <p>チアーズGO! にある自分の記録を、いつでもダウンロードしたり、まとめて消したりできます。</p>
      <div class="pv-stats"><div><b class="num">${fmt(n)}</b><small>この端末の記録</small></div><div><b class="num">0</b><small>保存した音声</small></div><div><b>${pvAgreed() ? ico("shieldok") : "—"}</b><small>${pvAgreed() ? "AIに同意ずみ" : "AIは未同意"}</small></div></div></section>
    <section class="pv-card pv-dl"><div class="pv-row-h"><span class="pv-bico">${ico("download")}</span><div><h3>ダウンロードする</h3><p>サーバーにある記録（会話の文字起こし・添削・投稿・名鑑など）と、この端末の記録を1つのファイル（JSON）にまとめます。ほかの人の名前は入りません。</p></div></div>
      <button type="button" class="ds-btn-blue tap" data-pvdl ${canAct || DEMO ? "" : "disabled"}>${ico("download")}私のデータをダウンロード</button>
      <p class="pv-note" id="pvDlNote">${canAct || DEMO ? "1日20回まで。ファイルは、あなただけが見られる場所に保存してください。" : esc(noApiMsg())}</p></section>
    <section class="pv-card pv-ai" id="pvAi"><div class="pv-row-h"><span class="pv-bico gold">${ico("book")}</span><div><h3>学びノートをAIに使う</h3>
      <p>Discordのやりとり・レッスンやレベルチェックの記録などから、名前や連絡先を伏せてAIが作った「あなたの学びのまとめ」を、AI英会話や質問ボットに使います。体調や病気などの話は入れません。いつでもオフにできます。</p></div></div>
      <label class="pv-sw"><span><b>学びノートを使う</b><small id="pvAiNote">はじめはオフです</small></span><input type="checkbox" role="switch" data-pvai ${canAct || DEMO ? "" : "disabled"}><i aria-hidden="true"></i></label></section>
    <section class="pv-card pv-zone"><div class="pv-row-h"><span class="pv-bico red">${ico("trash")}</span><div><h3>すべて消す</h3><p>サーバーにあるあなたの記録を、まとめて消します。<b>消したら元に戻せません。</b></p></div></div>
      <ul class="pv-dels">${PV_DEL_LIST.map(([i, t]) => `<li>${ico(i)}<span>${esc(t)}</span></li>`).join("")}</ul>
      <p class="pv-note">残るもの：あなたのリンク（ログイン）・運営が作るあなたのページ（Discord の投稿・写真のポイント。消したいときは窓口へ）・使いすぎ防止の回数（今週・今月の分だけ。中身は入っていません）。</p>
      <button type="button" class="pv-danger tap" data-pvdel ${canAct || DEMO ? "" : "disabled"}>${ico("trash")}すべて消す…</button></section>
    <button type="button" class="pv-link-row tap" data-pvgo="policy">${ico("shield")}<span><b>個人情報の扱い</b><small>何を・どこに・いつまで</small></span>${ico("chevron")}</button>`;
}
function pvDataOpen(){
  const el = pvScreen("私のデータ", pvDataHtml());
  el.querySelector("[data-pvgo='policy']").onclick = () => pvPolicyOpen();
  el.querySelector("[data-pvdl]").onclick = e => pvDownload(e.currentTarget);
  el.querySelector("[data-pvdel]").onclick = () => pvDeleteStep1();
  pvAiBind(el);
}
// 学びノートをAIに使う（オプトイン・初期はオフ）：中継の /api/privacy/ai-notes（デモは端末の cg-ainotes だけ）
const pvAiSay = r => r.on ? `オン${r.t ? "（" + esc(pvDay(r.t)) + " から）" : ""}：AI英会話・質問ボットが、あなたの学びのまとめを使います` : r.off_t ? `オフ（${esc(pvDay(r.off_t))}）：まとめは消しました。AIには使いません` : "はじめはオフです";
async function pvAiBind(el){
  const sw = el.querySelector("[data-pvai]"), note = el.querySelector("#pvAiNote"); if (!sw) return;
  const paint = r => { sw.checked = !!r.on; if (note) note.innerHTML = pvAiSay(r); el.querySelector("#pvAi").classList.toggle("on", !!r.on); };
  if (DEMO){ paint(store("cg-ainotes") === "1" ? {on: true} : {on: false}); }
  else if (apiOn() && API_AUTH){ try { paint(await api("/api/privacy/ai-notes")); } catch (e) { sw.disabled = true; if (note) note.textContent = "いまは設定を読めません（あとでもう一度どうぞ）"; } }
  sw.addEventListener("change", async () => {
    const want = sw.checked;
    if (DEMO){ store("cg-ainotes", want ? "1" : null); paint({on: want}); toast(want ? "オンにしました（デモ）" : "オフにしました（デモ）"); return; }
    sw.disabled = true;
    try { const r = await api("/api/privacy/ai-notes", {on: want}); paint(r); toast(r.on ? "学びノートをAIに使います" : "オフにしました。学びのまとめは消しました"); }
    catch (e) { sw.checked = !want; toast("変えられませんでした（" + e.message + "）", 4200); }
    sw.disabled = false;
  });
}
function pvSave(name, obj){
  const blob = new Blob([JSON.stringify(obj, null, 2)], {type: "application/json"}), url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = name; a.rel = "noopener"; document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 4000);
}
async function pvDownload(btn){
  const day = new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10), note = $("pvDlNote");
  btn.disabled = true; btn.classList.add("pv-busy");
  try {
    const server = DEMO ? {about: "デモの架空のデータです（サーバーには何も送っていません）", tables: {}} : await api("/api/me/export");
    const file = {app: "チアーズGO!", made: new Date().toISOString(), policy_ver: PV_VER, server, this_device: pvLocalDump()};
    pvSave(`cheers-go-my-data-${day}.json`, file);
    const n = (server.count || 0) + Object.keys(file.this_device).length;
    if (note) note.innerHTML = `${ico("check")}<span><b>${fmt(n)}</b> 件の記録をまとめました（cheers-go-my-data-${day}.json）</span>`;
    if (note) note.classList.add("ok");
    toast(DEMO ? "デモのデータをダウンロードしました" : "ダウンロードしました");
  } catch (e) { toast("ダウンロードできませんでした（" + e.message + "）", 4200); }
  btn.disabled = false; btn.classList.remove("pv-busy");
}
// 1段目：何が消えるか・元に戻せないことを確かめる
function pvDeleteStep1(){
  const {d, close} = pvSheet(`<div class="pv-sh-ic warn">${ico("trash")}</div><h3 class="pv-sh-t" id="pvd1">すべて消しますか？</h3>
    <p class="pv-sh-p">サーバーにあるあなたの記録を、まとめて消します。この端末の練習の記録も消えます（リンクと表示の設定は残ります）。</p>
    <ul class="pv-dels sm">${PV_DEL_LIST.map(([i, t]) => `<li>${ico(i)}<span>${esc(t)}</span></li>`).join("")}</ul>
    <label class="pv-ack"><input type="checkbox" data-pvack><span>消したら元に戻せないことが、わかりました</span></label>
    <p class="pv-sh-hint">先にダウンロードしておくと安心です。ほかの端末にも記録が残っていたら、その端末でも消してください。</p>
    <div class="pv-acts"><button type="button" class="pv-danger tap" data-pvnext disabled>次へ</button><button type="button" class="pv-ghost tap" data-pvx>やめる</button></div>`, "sm");
  d.setAttribute("aria-labelledby", "pvd1");
  d.addEventListener("click", e => { if (e.target === d || e.target.closest("[data-pvx]")) close(); });
  const ack = d.querySelector("[data-pvack]"), nx = d.querySelector("[data-pvnext]");
  ack.addEventListener("change", () => { nx.disabled = !ack.checked; });
  nx.onclick = () => { close(); setTimeout(pvDeleteStep2, reduce ? 0 : 200); };
}
// 2段目：「消す」と入れてから、最後のボタン
function pvDeleteStep2(){
  const {d, close} = pvSheet(`<div class="pv-sh-ic red">${ico("trash")}</div><h3 class="pv-sh-t" id="pvd2">最後の確認</h3>
    <p class="pv-sh-p">下の欄に <b class="pv-word">消す</b> と入れると、ボタンが押せるようになります。</p>
    <label class="pv-type"><span>確認のことば</span><input type="text" data-pvword autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="消す" inputmode="text"></label>
    <div class="pv-acts"><button type="button" class="pv-danger solid tap" data-pvgo2 disabled>${ico("trash")}完全に消す</button><button type="button" class="pv-ghost tap" data-pvx>やめる</button></div>`, "sm");
  d.setAttribute("aria-labelledby", "pvd2");
  d.addEventListener("click", e => { if (e.target === d || e.target.closest("[data-pvx]")) close(); });
  const inp = d.querySelector("[data-pvword]"), go = d.querySelector("[data-pvgo2]");
  inp.addEventListener("input", () => { go.disabled = inp.value.trim() !== "消す"; });
  setTimeout(() => { try { inp.focus({preventScroll: true}); } catch (e) {} }, 320);
  go.onclick = async () => {
    go.disabled = true; inp.disabled = true; go.classList.add("pv-busy"); go.lastChild.textContent = "消しています…";
    let n = 0;
    if (!DEMO){
      try { const r = await api("/api/me/delete", {confirm: "消す"}); n = r.n || 0; }
      catch (e) { toast("消せませんでした（" + e.message + "）", 4200); go.disabled = false; inp.disabled = false; go.classList.remove("pv-busy"); go.lastChild.textContent = "完全に消す"; return; }
      try { const keep = {}; PV_KEEP_LOCAL.forEach(k => { const v = store(k); if (v != null) keep[k] = v; }); localStorage.clear(); Object.entries(keep).forEach(([k, v]) => store(k, v)); } catch (e) {}
      PV.state = false; PV.t = null;
    }
    d.querySelector(".pv-sheet-in").innerHTML = `<div class="pv-done"><span class="pv-sh-ic ok">${ico("check")}</span><h3 class="pv-sh-t">消しました</h3>
      <p class="pv-sh-p">${DEMO ? "デモなので、何も消していません（見た目だけ）。" : `サーバーの記録 <b class="num">${fmt(n)}</b> 件と、この端末の練習の記録を消しました。消したことだけを記録に残しています（中身は残していません）。`}</p>
      <button type="button" class="ds-btn-blue tap" data-pvfin>${DEMO ? "閉じる" : "アプリを開きなおす"}</button></div>`;
    d.querySelector("[data-pvfin]").onclick = () => { close(); if (!DEMO){ pvScreenClose(true); location.reload(); } };
  };
}

/* ---------- 設定の行（マイ＞設定＞プライバシー） ---------- */
function pvSetRender(){
  const a = $("spPrivacy"), b = $("spMyData"); if (!a || !b) return;
  const show = !!ME;
  a.hidden = b.hidden = !show; if (!show) return;
  a.innerHTML = `<button type="button" class="pv-srow tap" data-pvopen="policy"><span><b>個人情報の扱い</b><small>${pvAgreed() ? `同意ずみ${PV.t ? "・" + esc(pvDay(PV.t)) : ""}` : "AIを使う前に読む・同意する"}</small></span>${pvAgreed() ? `<i class="pv-ok-dot" aria-label="同意ずみ"></i>` : ""}${ico("chevron")}</button>`;
  b.innerHTML = `<button type="button" class="pv-srow tap" data-pvopen="data"><span><b>私のデータ</b><small>ダウンロード・すべて消す</small></span>${ico("chevron")}</button>`;
}
document.addEventListener("click", e => { const b = e.target.closest && e.target.closest("[data-pvopen]"); if (!b) return; if (b.dataset.pvopen === "data") pvDataOpen(); else pvPolicyOpen(); });
(function pvSetWatch(){
  const sp = $("setPanel"); if (!sp) return;
  new MutationObserver(() => { if (!sp.hidden){ pvSetRender(); if (!DEMO && apiOn() && API_AUTH && PV.state === null) pvRefresh(); } }).observe(sp, {attributes: true, attributeFilter: ["hidden"]});
})();

/* ---------- 入力の注意：電話番号・メールアドレス・住所らしい文字 ---------- */
// 全角の数字・記号を半角に（「０９０－１２３４－５６７８」も見つける）
const pvHalf = s => String(s || "").replace(/[０-９Ａ-Ｚａ-ｚ＠．－＋]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0)).replace(/[ー―‐−–—]/g, "-");
function pvFindContact(text){
  const t = pvHalf(text), out = [];
  if (/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+/.test(t)) out.push("mail");
  const tel = t.match(/(\+81[-\s]?|0)\d{1,4}[-\s(]?\d{1,4}[-\s)]?\d{3,4}/g) || [];
  if (tel.some(x => { const n = x.replace(/\D/g, "").replace(/^81/, "0"); return n.length >= 10 && n.length <= 11; })) out.push("tel");
  const pref = /(東京都|北海道|京都府|大阪府|[一-龥]{2,3}県)/, city = /[一-龥ぁ-んァ-ヶ]{1,6}[市区町村郡]/, num = /\d+\s*丁目|\d+\s*番地?|\d+-\d+(-\d+)?|[一二三四五六七八九十]+丁目/;
  if (/〒\s*\d{3}-?\d{4}/.test(t) || (num.test(t) && (pref.test(t) || city.test(t)) && /(丁目|番地?|号|\d+-\d+)/.test(t))) out.push("addr");
  return out;
}
const PV_KIND = {tel: "電話番号", mail: "メールアドレス", addr: "住所"};
// 送る前に見る：見つからなければ true。見つかったら「直す／このまま送る」（block にある種類は「直す」だけ）
function pvCheckSend(texts, opt = {}){
  const found = [...new Set([].concat(texts || []).flatMap(x => pvFindContact(x)))];
  if (!found.length) return Promise.resolve(true);
  const block = found.filter(k => (opt.block || []).includes(k));
  return new Promise(resolve => {
    const names = found.map(k => PV_KIND[k]).join("・");
    const {d, close} = pvSheet(`<div class="pv-sh-ic warn">${ico("phone")}</div><h3 class="pv-sh-t" id="pvwT">${block.length ? "連絡先は、ここには書けません" : "ほかの人の連絡先は書かないでね"}</h3>
      <p class="pv-sh-p"><b>${esc(names)}</b>らしい文字が入っています。${block.length ? esc(opt.blockMsg || "名鑑に載せられないので、消してから保存してください。") : `${esc(opt.where || "ここ")}は、チアーズメイトのメンバーと運営に見えます。あなたや、ほかの人の連絡先・住所は書かないでください。`}</p>
      <div class="pv-found">${found.map(k => `<span class="pv-chip warn">${ico(k === "mail" ? "mail" : k === "tel" ? "phone" : "pin")}${PV_KIND[k]}</span>`).join("")}</div>
      <div class="pv-acts"><button type="button" class="ds-btn-gold tap" data-pvfix>${ico("pencil")}直す</button>${block.length ? "" : `<button type="button" class="pv-ghost tap" data-pvsend>このまま送る</button>`}</div>`, "sm pv-warn");
    d.setAttribute("aria-labelledby", "pvwT");
    const done = v => { close(); resolve(v); };
    d.addEventListener("click", e => { if (e.target === d) done(false); });
    d.querySelector("[data-pvfix]").onclick = () => done(false);
    const s = d.querySelector("[data-pvsend]"); if (s) s.onclick = () => done(true);
  });
}

/* ================= 「学びノート」をAIに使うか、はじめに1回だけ聞く（docs/ai-notes-onboard-1107.md） ================= */
/* 出すところ：
   ① 個人情報の扱いの同意シート（_part_privacy.js の pvConsentSheet）で「同意して始める」を押した直後に、同じシートの2ページ目として
   ② もう同意している人には、次にアプリを開いたとき1回だけ（中継の ai_notes_consent でまだ選んでいない＝オンにしたことも外したこともない人だけ）
   本当の選択にする：はじめはオフ。「オンにする」「今はしない」は同じ大きさ・同じ見た目のボタン。「今はしない」でも何も困らないと書く。
   記録：オンのときだけ中継（POST /api/privacy/ai-notes {on:true}）に書く。「今はしない」は中継に何も書かず、端末に「聞いた」印（cg-ainotes-asked）だけ。
   基本の同意（privacy_consent）とは別。デモでは見せるだけで送らない（端末の cg-ainotes だけ）。
   見た目は privacy.css の pv- の部品と app/ainotes.css（an-）。絵文字は使わず ico() */
const AN_ASKED = "cg-ainotes-asked";
const anAsked = () => !!store(AN_ASKED);
const AN_WHERE = "マイ＞設定＞プライバシー＞私のデータ";
function anHtml(){
  return `<div class="pv-hero pv-hero-c an-hero"><span class="pv-orb" aria-hidden="true">${ico("book")}</span><span class="pv-ey">あなたが決められます</span>
      <h2 id="anT" tabindex="-1">「学びノート」を<br>AIに使いますか？</h2><p>これまでの学びをまとめた、あなた専用のノートです。使っても使わなくても大丈夫。あとからいつでも変えられます。</p></div>
    <section class="pv-card"><h3 class="pv-h3">${ico("doc")}学びノートって？</h3>
      <p class="an-p">Discordのやりとり・レッスン・レベルチェック・貿易のやりとり（抹茶のDMの数など）から、AIがあなた専用のまとめを作ります。苦手な表現・目標・いまの貿易の状況などが入ります。</p></section>
    <section class="pv-card"><h3 class="pv-h3">${ico("sparkles")}使うと、こうなります</h3>
      <ul class="an-list"><li>${ico("mic")}<span><b>AI英会話</b>が、あなたの苦手な表現や目標に合わせて、話題や練習を選びます</span></li>
        <li>${ico("chat")}<span><b>質問ボット</b>が、あなたの商材・国・いまの状況をふまえて答えます</span></li>
        <li>${ico("repeat")}<span>新しい記録でまとめを作り直すので、続けるほどあなたに合っていきます</span></li></ul></section>
    <section class="pv-card"><h3 class="pv-h3">${ico("shield")}気をつけていること</h3>
      <ul class="an-list"><li>${ico("lock")}<span>名前・連絡先・金額・取引先の名前は伏せます。<b>体調や病気などの話は入れません</b></span></li>
        <li>${ico("globe")}<span>まとめは <b>Google（米国）のAI</b>（Gemini）で作り、Cloudflare（米国）のサーバーに置きます</span></li>
        <li>${ico("eye")}<span>使うのは、あなたのAI英会話と質問ボットだけ。ほかの人には見せません</span></li>
        <li>${ico("gear")}<span>${AN_WHERE} で、いつでも切りかえられます。オフにすると、ノートは消えます</span></li></ul></section>
    <p class="an-free">${ico("check")}<span>「今はしない」を選んでも、困ることはありません。AI英会話も質問ボットも、今までどおり使えます。</span></p>
    <div class="an-acts" role="group" aria-label="学びノートをAIに使うか"><button type="button" class="an-btn tap" data-anon>${ico("book")}オンにする</button><button type="button" class="an-btn tap" data-anlater>${ico("clock")}今はしない</button></div>`;
}
const AN_LATER = `今はしないにしました。あとで ${AN_WHERE} から変えられます`;
// 答えを決める。オンのときだけ中継に送る（同意を送り終わってから）。デモは送らない
async function anChoose(on){
  store(AN_ASKED, new Date().toISOString());
  if (!on) return false;
  if (DEMO){ store("cg-ainotes", "1"); toast("オンにしました（デモなので送っていません）"); return true; }
  try {
    await pvWait();
    const r = await api("/api/privacy/ai-notes", {on: true});
    toast(r.on ? "学びノートをAIに使います" : "オンにできませんでした", 3200);
    if (typeof AIM !== "undefined"){ AIM = null; AIMP = null; }       // 学びノートの印（_part_aimatome.js）は次に開いたとき聞き直す
    return !!r.on;
  } catch (e) {
    store(AN_ASKED, null);                                            // 送れなかったときは、次にまた聞く
    toast(`いまはオンにできませんでした。${AN_WHERE} から、あとでどうぞ`, 4600);
    return false;
  }
}
// 同意シートの2ページ目にするか（この端末でまだ聞いていない人）
const anNeed = () => !anAsked();
// 同意シートの中身を学びノートのページに差しかえる。done() は同意シートの答え（同意した＝true）を返す
function anShowIn(sheetIn, done){
  const sh = sheetIn.closest(".pv-sheet");
  sheetIn.innerHTML = anHtml(); sheetIn.scrollTop = 0;
  if (sh){ sh.classList.add("an-sheet"); sh.setAttribute("aria-labelledby", "anT"); }
  sheetIn.querySelector("[data-anon]").onclick = () => { anChoose(true); done(); };
  sheetIn.querySelector("[data-anlater]").onclick = () => { anChoose(false); toast(AN_LATER, 4200); done(); };
  try { sheetIn.querySelector("#anT").focus({preventScroll: true}); } catch (e) {}   // 見出しに（どちらかのボタンだけ目立たせない）
}
// もう同意している人：次に開いたとき1回だけ（ほかのシート・画面が出ているあいだは待つ）
async function anOnOpen(tries = 0){
  if (DEMO || !apiOn() || !API_AUTH || (ME && ME.viewer) || anAsked() || !pvAgreed()) return;
  const busy = document.querySelector(".pv-sheet, .pv-screen, dialog[open]") || [...document.querySelectorAll('[role="dialog"]')].some(e => !e.hidden && e.offsetParent);
  if (busy){ if (tries < 4) setTimeout(() => anOnOpen(tries + 1), 6000); return; }
  let r;
  try { r = await api("/api/privacy/ai-notes"); } catch (e) { return; }   // 古い中継・つながらない：次に開いたときに
  if (r.on || r.off_t){ store(AN_ASKED, r.t || r.off_t || "server"); return; }   // もう選んだことがある（ほかの端末でも）
  if (anAsked() || document.querySelector(".pv-sheet")) return;
  const {d, close} = pvSheet(anHtml(), "pv-consent an-sheet");
  d.setAttribute("aria-labelledby", "anT");
  setTimeout(() => { try { d.querySelector("#anT").focus({preventScroll: true}); } catch (e) {} }, 300);
  const fin = () => { close(); document.removeEventListener("keydown", k); };
  const k = e => { if (e.key === "Escape"){ anChoose(false); fin(); } };
  document.addEventListener("keydown", k);
  d.addEventListener("click", e => { if (e.target === d){ anChoose(false); fin(); } });   // 外を押して閉じた＝今はしない
  d.querySelector("[data-anon]").onclick = () => { anChoose(true); fin(); };
  d.querySelector("[data-anlater]").onclick = () => { anChoose(false); toast(AN_LATER, 4200); fin(); };
}
/* ================= 設定の全画面（2026-11-06・docs/settings-1106.md） =================
   右上の歯車（ほかに マイ＞設定・ベルの「リマインド・通知の設定」・はじめの1週間ガイド）で開く #setPanel を、
   下のタブの中身が見えない「単独の全画面」にする。中の行（#spRemind・#spSpeak・#spToast・#spChPrefs・#spGuide）は今までどおり各部品が描く。
   - 開く：#setPanel の hidden が外れたら（どこから開いても）右からスライドして入る。下のページはその位置で止める（スクロール固定）
   - 閉じる：「戻る」・Esc・左端からのスワイプ・ブラウザ／スマホの「戻る」（history に1つ積む。URL と # の鍵は変えない）。来た方向（右）へ抜けて、元のタブの元の位置に戻る
   - 動き：0.25〜0.35秒。prefers-reduced-motion のときはフェードだけ
   - popstate はこのファイルが _part_go.js（共通の戻る帯）より先に受けて、設定が開いているあいだは帯に渡さない */
