// 中の行が出ていないもの（使えない環境・先生リンクなど）は、アイコンごと・まとまりごとかくす
function stSync(){
  stEl.querySelectorAll(".st-item").forEach(it => { const r = it.querySelector(".sp-row"); it.hidden = !!(r && r.hidden); });
  stEl.querySelectorAll(".st-card").forEach(c => {
    const off = !c.querySelector(".st-item:not([hidden])"); c.hidden = off;
    const h = c.previousElementSibling; if (h && h.classList.contains("st-gh")) h.hidden = off;
  });
}
function stLock(){
  ST.y = window.scrollY;
  document.body.style.top = -ST.y + "px"; document.body.classList.add("st-lock");
}
function stUnlock(){
  if (!document.body.classList.contains("st-lock")) return;
  document.body.classList.remove("st-lock"); document.body.style.top = "";
  const y = ST.y; window.scrollTo(0, y); requestAnimationFrame(() => { if (Math.abs(window.scrollY - y) > 1) window.scrollTo(0, y); });
}
function stOnShow(){
  ST.open = true; ST.closing = false; clearTimeout(ST.t);
  $("gear").setAttribute("aria-expanded", "true");
  if (typeof engPanel === "function") engPanel(false);
  $("stHero").innerHTML = stHeroHtml();
  if (typeof tlSetRender === "function") tlSetRender();                    // タイムライン（自動でシェア・夜のまとめ通知・ミュート中の人。app/_part_tl.js）
  stSync();
  stBody.scrollTop = 0; stEl.style.transition = stEl.style.transform = stEl.style.opacity = "";
  // 積むのはページを止める前（ブラウザが「戻る」で元の位置を覚えたまま戻せるように）
  try { history.pushState({cgst: 1}, "", location.href); ST.pushed = true; } catch (e) { ST.pushed = false; }
  stLock();
  stEl.classList.remove("st-out"); void stEl.offsetWidth; stEl.classList.add("st-in");
  stScrim.classList.add("on");
  ST.t = setTimeout(() => { stEl.classList.remove("st-in"); try { $("stBack").focus({preventScroll: true}); } catch (e) {} }, 380);
}
function stDone(){
  stEl.hidden = true; stEl.classList.remove("st-in", "st-out"); stEl.style.transition = stEl.style.transform = stEl.style.opacity = "";
  ST.open = false; ST.closing = false;
  $("gear").setAttribute("aria-expanded", "false");
}
// 右へ抜ける（スワイプの途中からでも、その位置から）。下のページは先に元の位置へ戻しておく
function stAnimOut(){
  if (!ST.open || ST.closing) return;
  ST.closing = true; clearTimeout(ST.t);
  stUnlock(); stScrim.classList.remove("on");
  const cur = getComputedStyle(stEl).transform;
  stEl.classList.remove("st-in");
  if (reduce){ stEl.style.transition = "opacity .2s ease"; stEl.style.opacity = "0"; }
  else {
    stEl.style.transition = "none"; stEl.style.transform = cur === "none" ? "translateX(0)" : cur; void stEl.offsetWidth;
    stEl.style.transition = "transform .28s cubic-bezier(.4,0,.8,.4)"; stEl.style.transform = "translateX(100%)";
  }
  ST.t = setTimeout(() => { stDone(); try { $("gear").focus({preventScroll: true}); } catch (e) {} }, reduce ? 210 : 290);
}
// 「戻る」：積んだ1つを戻す → popstate で stAnimOut。戻せなかったときの保険つき
function stClose(){
  if (!ST.open || ST.closing) return;
  if (ST.pushed){ history.back(); setTimeout(() => { if (ST.open && !ST.closing){ ST.pushed = false; stAnimOut(); } }, 450); }
  else stAnimOut();
}
// すぐ閉じる（ガイドを開く・ようこその案内など、ほかの画面へ移るとき）。積んだ1つは黙って戻す
function stHide(){
  if (!ST.open){ stEl.hidden = true; return; }
  ST.closing = true; clearTimeout(ST.t);
  stUnlock(); stScrim.classList.remove("on"); stDone();
  if (ST.pushed){ ST.pushed = false; ST.skip++; history.back(); }
}
window.addEventListener("popstate", e => {
  if (ST.skip){ ST.skip--; e.stopImmediatePropagation(); return; }
  if (ST.open && !ST.closing){ ST.pushed = false; e.stopImmediatePropagation(); stAnimOut(); }
});
new MutationObserver(() => {
  if (!stEl.hidden && !ST.open) stOnShow();
  else if (stEl.hidden && ST.open && !ST.closing){ stUnlock(); stScrim.classList.remove("on"); stDone(); if (ST.pushed){ ST.pushed = false; ST.skip++; history.back(); } }
}).observe(stEl, {attributes: true, attributeFilter: ["hidden"]});
let stSyncRaf = 0;
new MutationObserver(() => { if (!stSyncRaf) stSyncRaf = requestAnimationFrame(() => { stSyncRaf = 0; stSync(); }); })
  .observe(stBody, {attributes: true, attributeFilter: ["hidden"], subtree: true});
$("stBack").addEventListener("click", stClose);
document.addEventListener("keydown", e => { if (e.key === "Escape" && ST.open) stClose(); });
// 左端からのスワイプで戻る（指についてくる。1/3 以上か、速く払ったら閉じる）
(function stSwipe(){
  let x0 = 0, y0 = 0, t0 = 0, dx = 0, on = false, decided = false;
  stEl.addEventListener("touchstart", e => {
    if (!ST.open || ST.closing || e.touches.length !== 1 || e.touches[0].clientX > 28) return;
    on = true; decided = false; dx = 0; x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; t0 = Date.now();
  }, {passive: true});
  stEl.addEventListener("touchmove", e => {
    if (!on) return;
    const x = e.touches[0].clientX - x0, y = e.touches[0].clientY - y0;
    if (!decided){ if (Math.abs(x) < 6 && Math.abs(y) < 6) return; decided = true; if (Math.abs(y) > Math.abs(x) || x < 0){ on = false; return; } stEl.classList.remove("st-in"); }
    e.preventDefault();
    dx = Math.max(0, x);
    stEl.style.transition = "none"; stEl.style.transform = `translateX(${dx}px)`;
    stScrim.style.opacity = String(Math.max(0, 1 - dx / innerWidth));
  }, {passive: false});
  const end = () => {
    if (!on) return; on = false; stScrim.style.opacity = "";
    if (!decided) return;
    const v = dx / Math.max(1, Date.now() - t0);
    if (dx > innerWidth / 3 || (v > 0.5 && dx > 30)) stClose();
    else { stEl.style.transition = "transform .22s cubic-bezier(.2,.8,.2,1)"; stEl.style.transform = "translateX(0)"; }
  };
  stEl.addEventListener("touchend", end); stEl.addEventListener("touchcancel", end);
})();

