/* ---------- わたしの歩み（2026-11-06・docs/home-my-1106.md）：マイの主役。英語・貿易・乾杯の3本柱の積み上げ ---------- */
// 入会して何日目か：はじめて開いた日（はじめの1週間ガイドの1日目）・はじめての乾杯・はじめての練習のいちばん前
function myJoinDay(d){
  const xs = [typeof obStart === "function" ? obStart() : "", (d.photos[0] || {}).d || "", [...studySet(d)].sort()[0] || ""].filter(Boolean).sort();
  return xs[0] || dayKey(Date.now());
}
const myDayN = d => Math.floor((new Date(dayKey(Date.now()) + "T12:00:00") - new Date(myJoinDay(d) + "T12:00:00")) / 864e5) + 1;
// 英語：練習した日数・話す速さ（語/分・基準155＝スピード練習と音読チェックのベスト）・答える速さ（秒・基準2＝2秒応答の最近20回の平均）
function myEngStats(d){
  const j = k => { try { return JSON.parse(store(k) || "[]"); } catch (e) { return []; } };
  const wpm = Math.max(0, ...j("kz-log").map(x => +x.wpm || 0), ...j("kz-reads").map(x => +x.wpm || 0));
  const ms = j("kz-react").filter(x => x && x.ms > 0).slice(-20).map(x => x.ms);
  return {days: studySet(d).size, wpm: wpm || null, sec: ms.length ? Math.round(ms.reduce((s, v) => s + v, 0) / ms.length / 100) / 10 : null};
}
// 貿易：貿易ダッシュボードと同じ数字（trdData があればそれ・なければ main の数え方＝この端末の送信完了の記録。デモは架空の割合）
function myTrStats(){
  if (typeof trdData === "function"){ const D = trdData("all"), st = D.st || {}; return {sent: D.sent, reply: st.reply, sample: st.sample, order: st.order}; }
  if (typeof trqLog !== "function") return {sent: 0};
  const sent = Object.values(trqLog()).reduce((s, o) => s + Object.values(o || {}).reduce((a, v) => a + (+v || 0), 0), 0);
  return DEMO ? {sent, reply: Math.round(sent * .116), sample: Math.round(sent * .035), order: Math.round(sent * .01)} : {sent};
}
const myV = (v, u) => `<span class="v">${v == null ? `<b class="num">まだ</b>` : `<b class="num">${fmt(v)}</b>${u ? `<small>${u}</small>` : ""}`}</span>`;
