    <g clip-path="url(#${u}c)" class="tra-grid"><path d="M10 34h76M10 46h76M10 58h76M10 70h76M22 14v80M36 14v80M50 14v80M64 14v80M78 14v80"/><path class="tra-road" d="M6 76C26 66 30 50 48 52s30-14 44-26"/></g>
