// 住所検索の英語名 → 選択肢リストの書き方
const NC_CC_ALIAS = {"united states": "USA", "united states of america": "USA", "us": "USA", "america": "USA", "united kingdom": "UK", "great britain": "UK", "england": "UK", "czechia": "Czech", "czech republic": "Czech", "côte d'ivoire": "Ivory Coast", "cote d'ivoire": "Ivory Coast", "republic of korea": "South Korea", "korea": "South Korea", "türkiye": "Turkey", "turkiye": "Turkey", "uae": "United Arab Emirates", "viet nam": "Vietnam", "russian federation": "Russia", "lao people's democratic republic": "Laos", "brunei darussalam": "Brunei", "cape verde": "Cabo Verde", "holy see": "Vatican City", "the netherlands": "Netherlands", "hong kong sar china": "Hong Kong"};
function ncCcOpt(s){ s = String(s || "").trim(); if (!s) return ""; const l = s.toLowerCase(); return NC_CC.find(c => c.toLowerCase() === l) || NC_CC_ALIAS[l] || ""; }
const NC_DAYS = 30;   // 30日以内に誰かが連絡していたら止める

