  const add = sub => `${need}<button type="button" class="ds-btn-gold nc-reg" data-ncadd${need || NC.busy ? " disabled" : ""}>${ico("plus")}送信候補に追加</button>${sub ? `<p class="nc-reg-sub">${sub}</p>` : ""}`;
  const SUB = "送信候補に入れておいて、お店に送ったら「送った！」を押すと全体共有リストに記録されます（送るまではリストに入りません）。";
